def get_current_scene_info(detailLevel=None, **_extra):
    import json, os, datetime, time, uuid, copy

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0289000" if __import__("os").path.isdir("./environment_mix/0289000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _dt_parse(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            d = datetime.datetime.fromisoformat(s)
            return d if d.tzinfo else d.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _dt_dump(d):
        if d is None:
            return None
        if isinstance(d, str):
            return d
        if not isinstance(d, datetime.datetime):
            return None
        return d.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _pick_active_session(sessions, staleness_window_seconds=30):
        now = _now()
        best = None
        best_hb = None
        for s in sessions:
            if not isinstance(s, dict):
                continue
            if s.get("status") != "connected":
                continue
            hb = _dt_parse(s.get("last_heartbeat_at"))
            if hb is None:
                continue
            age = (now - hb).total_seconds()
            if age < 0:
                age = 0
            if age <= staleness_window_seconds:
                if best is None or hb > best_hb:
                    best = s
                    best_hb = hb
        return best, staleness_window_seconds

    def _record_inv(session_id, status, request_params, response_body=None, error_message=None, error_details=None, related_scene_snapshot_id=None):
        inv_file = "tool_invocations.json"
        invocations = _load(inv_file)
        now_iso = _dt_dump(_now())
        row = {
            "id": _new_id("inv"),
            "session_id": session_id,
            "status": status,
            "tool_name": "get_current_scene_info",
            "request_params": request_params if isinstance(request_params, dict) else {},
            "response_body": response_body,
            "error_message": error_message,
            "error_details": error_details,
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "related_scene_snapshot_id": related_scene_snapshot_id,
            "related_entry_ids": None,
            "file_path": None,
            "paths": None,
            "code": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        invocations.append(row)
        _save(inv_file, invocations)
        return row["id"]

    # Validate
    if detailLevel is None:
        detailLevel = "RootObjectsOnly"
    if not isinstance(detailLevel, str) or detailLevel not in ("RootObjectsOnly", "FullHierarchy"):
        _record_inv(None, "failed", {"detailLevel": detailLevel}, error_message="Validation error", error_details={"field": "detailLevel"})
        return _err("VALIDATION_ERROR", "detailLevel must be one of: RootObjectsOnly, FullHierarchy.", field="detailLevel")

    sessions = _load("unity_editor_sessions.json")
    active, staleness_window_seconds = _pick_active_session(sessions, 30)
    if not active:
        _record_inv(None, "failed", {"detailLevel": detailLevel}, error_message="No active Unity Editor connection", error_details={"staleness_window_seconds": staleness_window_seconds})
        return _err("UNAUTHORIZED", "No active Unity Editor connection", staleness_window_seconds=staleness_window_seconds)

    session_id = active.get("id")

    snapshots = _load("scene_snapshots.json")
    # latest snapshot for session by captured_at then created_at
    latest = None
    latest_key = None
    for sn in snapshots:
        if not isinstance(sn, dict):
            continue
        if sn.get("session_id") != session_id:
            continue
        # Prefer captured snapshots; if none exist, allow other statuses but still "latest"
        cap = _dt_parse(sn.get("captured_at")) or _dt_parse(sn.get("created_at")) or _dt_parse(sn.get("updated_at"))
        if cap is None:
            continue
        key = (cap, sn.get("created_at") or "", sn.get("id") or "")
        if latest is None or key > latest_key:
            latest = sn
            latest_key = key

    if latest is None:
        _record_inv(session_id, "failed", {"detailLevel": detailLevel}, error_message="No scene snapshot available", error_details={"session_id": session_id})
        return _err("NOT_FOUND", "No scene snapshot available for the active session.", session_id=session_id)

    # Determine whether we need a more detailed snapshot
    need_full = (detailLevel == "FullHierarchy")
    latest_detail = latest.get("capture_detail_level")
    if latest_detail not in ("RootObjectsOnly", "FullHierarchy"):
        # Treat as unusable snapshot
        _record_inv(session_id, "failed", {"detailLevel": detailLevel}, error_message="Invalid snapshot detail level", error_details={"snapshot_id": latest.get("id")}, related_scene_snapshot_id=latest.get("id"))
        return _err("NOT_FOUND", "Latest snapshot is invalid or incomplete.", snapshot_id=latest.get("id"))

    if need_full and latest_detail == "RootObjectsOnly":
        # Capture a new FullHierarchy snapshot (server-side) and supersede the old latest if allowed
        # Supersede transition: captured -> superseded only
        if latest.get("status") == "captured":
            latest["status"] = "superseded"
            latest["updated_at"] = _dt_dump(_now())
        # Create new snapshot derived from existing
        new_sn = copy.deepcopy(latest)
        new_sn["id"] = _new_id("unity_scene")
        new_sn["status"] = "captured"
        new_sn["capture_detail_level"] = "FullHierarchy"
        now_iso = _dt_dump(_now())
        new_sn["captured_at"] = now_iso
        new_sn["created_at"] = now_iso
        new_sn["updated_at"] = now_iso
        # Ensure hierarchy / index exist; if not present, create minimal placeholders
        if new_sn.get("hierarchy") is None:
            # Best-effort: embed root objects list as a minimal "hierarchy"
            ro = new_sn.get("root_objects") if isinstance(new_sn.get("root_objects"), list) else []
            new_sn["hierarchy"] = {"root": ro}
        if new_sn.get("instance_index") is None:
            # Build minimal index from root_objects if possible
            idx = {}
            ro = new_sn.get("root_objects") if isinstance(new_sn.get("root_objects"), list) else []
            for obj in ro:
                if isinstance(obj, dict):
                    iid = obj.get("instanceID")
                    if isinstance(iid, (int, float)) and int(iid) not in idx:
                        idx[str(int(iid))] = obj
                    elif isinstance(iid, str) and iid not in idx:
                        idx[iid] = obj
            new_sn["instance_index"] = idx if idx else {}
        snapshots.append(new_sn)

        # Update session pointer
        active["last_scene_snapshot_id"] = new_sn["id"]
        active["updated_at"] = _dt_dump(_now())

        # Persist
        _save("scene_snapshots.json", snapshots)
        _save("unity_editor_sessions.json", sessions)

        latest = new_sn

    # Compose response derived from snapshot
    resp = {
        "sessionId": session_id,
        "scenePath": latest.get("scene_path"),
        "sceneName": latest.get("scene_name"),
        "activeBuildTarget": latest.get("active_build_target"),
        "detailLevel": latest.get("capture_detail_level"),
        "capturedAt": latest.get("captured_at"),
        "rootObjects": latest.get("root_objects") if isinstance(latest.get("root_objects"), list) else [],
    }
    if detailLevel == "FullHierarchy":
        resp["hierarchy"] = latest.get("hierarchy")
        # Include index when available; clients may use it
        resp["instanceIndex"] = latest.get("instance_index")

    _record_inv(session_id, "succeeded", {"detailLevel": detailLevel}, response_body=resp, related_scene_snapshot_id=latest.get("id"))
    return resp

def get_game_objects_info(instanceIDs, detailLevel=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0289000" if __import__("os").path.isdir("./environment_mix/0289000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _dt_parse(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            d = datetime.datetime.fromisoformat(s)
            return d if d.tzinfo else d.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _dt_dump(d):
        if d is None:
            return None
        if isinstance(d, str):
            return d
        if not isinstance(d, datetime.datetime):
            return None
        return d.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _pick_active_session(sessions, staleness_window_seconds=30):
        now = _now()
        best = None
        best_hb = None
        for s in sessions:
            if not isinstance(s, dict):
                continue
            if s.get("status") != "connected":
                continue
            hb = _dt_parse(s.get("last_heartbeat_at"))
            if hb is None:
                continue
            age = (now - hb).total_seconds()
            if age < 0:
                age = 0
            if age <= staleness_window_seconds:
                if best is None or hb > best_hb:
                    best = s
                    best_hb = hb
        return best, staleness_window_seconds

    def _record_inv(session_id, status, request_params, response_body=None, error_message=None, error_details=None, related_scene_snapshot_id=None):
        invocations = _load("tool_invocations.json")
        now_dt = _now()
        row = {
            "id": _new_id("unity_inv"),
            "session_id": session_id,
            "status": status,
            "tool_name": "get_game_objects_info",
            "request_params": request_params if isinstance(request_params, dict) else {},
            "response_body": response_body,
            "error_message": error_message,
            "error_details": error_details,
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "related_scene_snapshot_id": related_scene_snapshot_id,
            "related_entry_ids": None,
            "file_path": None,
            "paths": None,
            "code": None,
            "created_at": _dt_dump(now_dt),
            "updated_at": _dt_dump(now_dt),
        }
        invocations.append(row)
        _save("tool_invocations.json", invocations)
        return row

    # Validate inputs
    if not isinstance(instanceIDs, list) or len(instanceIDs) < 1:
        # still must log call; choose any session for logging if possible
        sessions = _load("unity_editor_sessions.json")
        sess, _ = _pick_active_session(sessions)
        sid = sess.get("id") if isinstance(sess, dict) else (sessions[0].get("id") if sessions else "unknown_session")
        _record_inv(sid, "failed", {"instanceIDs": instanceIDs, "detailLevel": detailLevel},
                    error_message="Validation error",
                    error_details=_err("VALIDATION_ERROR", "instanceIDs must be a non-empty array of numbers.", field="instanceIDs")["error"])
        return _err("VALIDATION_ERROR", "instanceIDs must be a non-empty array of numbers.", field="instanceIDs")

    if detailLevel is None:
        detailLevel = "IncludeComponents"
    if not isinstance(detailLevel, str) or detailLevel not in ["BasicInfo", "IncludeComponents", "IncludeChildren", "IncludeComponentsAndChildren"]:
        sessions = _load("unity_editor_sessions.json")
        sess, _ = _pick_active_session(sessions)
        sid = sess.get("id") if isinstance(sess, dict) else (sessions[0].get("id") if sessions else "unknown_session")
        _record_inv(sid, "failed", {"instanceIDs": instanceIDs, "detailLevel": detailLevel},
                    error_message="Validation error",
                    error_details=_err("VALIDATION_ERROR", "detailLevel must be one of the supported enum values.", field="detailLevel")["error"])
        return _err("VALIDATION_ERROR", "detailLevel must be one of the supported enum values.", field="detailLevel")

    norm_ids = []
    bad = []
    for x in instanceIDs:
        if not isinstance(x, (int, float)) or isinstance(x, bool):
            bad.append(x)
            continue
        if int(x) != x:
            bad.append(x)
            continue
        norm_ids.append(int(x))
    if bad:
        sessions = _load("unity_editor_sessions.json")
        sess, _ = _pick_active_session(sessions)
        sid = sess.get("id") if isinstance(sess, dict) else (sessions[0].get("id") if sessions else "unknown_session")
        _record_inv(sid, "failed", {"instanceIDs": instanceIDs, "detailLevel": detailLevel},
                    error_message="Validation error",
                    error_details=_err("VALIDATION_ERROR", "All instanceIDs must be numeric integers.", badInstanceIDs=bad)["error"])
        return _err("VALIDATION_ERROR", "All instanceIDs must be numeric integers.", badInstanceIDs=bad)

    sessions = _load("unity_editor_sessions.json")
    active, _ = _pick_active_session(sessions)
    if not active:
        # log against some existing session id if any
        sid = sessions[0].get("id") if sessions and isinstance(sessions[0], dict) else "unknown_session"
        _record_inv(sid, "failed", {"instanceIDs": instanceIDs, "detailLevel": detailLevel},
                    error_message="No active Unity Editor connection",
                    error_details=_err("UNAUTHORIZED", "No active Unity Editor connection (no connected session within staleness window).")["error"])
        return _err("UNAUTHORIZED", "No active Unity Editor connection (no connected session within staleness window).")

    session_id = active.get("id")
    snapshots = _load("scene_snapshots.json")
    # pick latest captured snapshot for the session (by captured_at then created_at)
    best = None
    best_dt = None
    for sn in snapshots:
        if not isinstance(sn, dict):
            continue
        if sn.get("session_id") != session_id:
            continue
        if sn.get("status") != "captured":
            continue
        dt = _dt_parse(sn.get("captured_at")) or _dt_parse(sn.get("created_at")) or _dt_parse(sn.get("updated_at"))
        if dt is None:
            continue
        if best is None or dt > best_dt:
            best, best_dt = sn, dt

    if not best:
        _record_inv(session_id, "failed", {"instanceIDs": instanceIDs, "detailLevel": detailLevel},
                    error_message="No current scene snapshot",
                    error_details=_err("NOT_FOUND", "No captured scene snapshot exists for the active session.")["error"],
                    related_scene_snapshot_id=None)
        return _err("NOT_FOUND", "No captured scene snapshot exists for the active session.")

    snapshot_id = best.get("id")

    index = best.get("instance_index")
    hierarchy = best.get("hierarchy")
    results = []
    missing = []

    def _resolve_node(iid):
        # Prefer instance_index if present; else try hierarchy lookup (dict keyed by instanceID as string/int)
        if isinstance(index, dict):
            if str(iid) in index:
                return index.get(str(iid))
            if iid in index:
                return index.get(iid)
        if isinstance(hierarchy, dict):
            if str(iid) in hierarchy:
                return hierarchy.get(str(iid))
            if iid in hierarchy:
                return hierarchy.get(iid)
        return None

    for iid in norm_ids:
        node = _resolve_node(iid)
        if node is None:
            missing.append(iid)
            results.append(None)
        else:
            # return node as-is; optionally trim depending on detailLevel (best-effort)
            if isinstance(node, dict):
                if detailLevel == "BasicInfo":
                    basic_keys = ["instanceID", "name", "activeSelf", "tag", "layer", "childCount", "parentInstanceID", "path"]
                    trimmed = {k: node.get(k) for k in basic_keys if k in node}
                    if "instanceID" not in trimmed:
                        trimmed["instanceID"] = iid
                    results.append(trimmed)
                else:
                    results.append(node)
            else:
                results.append({"instanceID": iid, "data": node})

    # Business rule: must report missing IDs but do not fail unless ALL are missing.
    if len(missing) == len(norm_ids):
        _record_inv(session_id, "succeeded", {"instanceIDs": instanceIDs, "detailLevel": detailLevel},
                    response_body={"scene_snapshot_id": snapshot_id, "gameObjects": [], "missingInstanceIDs": missing},
                    related_scene_snapshot_id=snapshot_id)
        return {"scene_snapshot_id": snapshot_id, "gameObjects": [], "missingInstanceIDs": missing}

    game_objects = [r for r in results if r is not None]
    _record_inv(session_id, "succeeded", {"instanceIDs": instanceIDs, "detailLevel": detailLevel},
                response_body={"scene_snapshot_id": snapshot_id, "gameObjects": game_objects, "missingInstanceIDs": missing},
                related_scene_snapshot_id=snapshot_id)
    return {"scene_snapshot_id": snapshot_id, "gameObjects": game_objects, "missingInstanceIDs": missing}

def execute_editor_command(code, **_extra):
    import json, os, datetime, time, uuid, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0289000" if __import__("os").path.isdir("./environment_mix/0289000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code_, msg, **x):
        return {"error": {"code": code_, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _dt_parse(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            d = datetime.datetime.fromisoformat(s)
            return d if d.tzinfo else d.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _dt_dump(d):
        if d is None:
            return None
        if isinstance(d, str):
            return d
        if not isinstance(d, datetime.datetime):
            return None
        return d.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _pick_active_session(sessions, staleness_window_seconds=30):
        now = _now()
        best = None
        best_hb = None
        for s in sessions:
            if not isinstance(s, dict):
                continue
            if s.get("status") != "connected":
                continue
            hb = _dt_parse(s.get("last_heartbeat_at"))
            if hb is None:
                continue
            age = (now - hb).total_seconds()
            if age < 0:
                age = 0
            if age <= staleness_window_seconds:
                if best is None or hb > best_hb:
                    best = s
                    best_hb = hb
        return best, staleness_window_seconds

    def _record_inv(session_id, status, request_params, response_body=None, error_message=None, error_details=None, code_field=None):
        inv_file = "tool_invocations.json"
        invocations = _load(inv_file)
        now_dt = _now()
        row = {
            "id": _new_id("unity_inv"),
            "session_id": session_id,
            "status": status,
            "tool_name": "execute_editor_command",
            "request_params": request_params if isinstance(request_params, dict) else {},
            "response_body": response_body,
            "error_message": error_message,
            "error_details": error_details,
            "duration_ms": int(max(0, (time.time() - t0) * 1000)),
            "related_scene_snapshot_id": None,
            "related_entry_ids": None,
            "file_path": None,
            "paths": None,
            "code": code_field,
            "created_at": _dt_dump(now_dt),
            "updated_at": _dt_dump(now_dt),
        }
        if not isinstance(invocations, list):
            invocations = []
        invocations.append(row)
        _save(inv_file, invocations)

    # Validate
    if not isinstance(code, str):
        return _err("VALIDATION_ERROR", "code must be a string.", field="code")
    if len(code) < 1:
        return _err("VALIDATION_ERROR", "code must be a non-empty string.", field="code", rule="minLength=1")
    # Optional safety cap per business rules
    if len(code) > 200000:
        return _err("QUOTA_EXCEEDED", "code exceeds maximum allowed length.", field="code", maxLength=200000)

    # Resolve active session
    sessions = _load("unity_editor_sessions.json")
    sess, _ = _pick_active_session(sessions)
    if not sess:
        return _err("UNAUTHORIZED", "No active Unity Editor connection is available.")

    # Vendor schema suggests it "compiles and executes"; offline datastore cannot execute.
    # Realistic behavior: accept valid code and record invocation; return an execution placeholder.
    # IMPORTANT: Do NOT over-validate code structure beyond minLength; prior audit defect was too strict.
    # Still record code; to avoid sensitive storage, store hash if extremely large; otherwise store verbatim.
    store_code = code if len(code) <= 50000 else ("sha256:" + hashlib.sha256(code.encode("utf-8")).hexdigest())

    response = {
        "status": "submitted",
        "result": None,
        "message": "Command accepted and recorded. Offline datastore cannot execute Unity Editor code.",
    }
    _record_inv(sess["id"], "succeeded", {"code": code}, response, code_field=store_code)
    return response

