                    best = s
                    best_hb = hb
        return best, staleness_window_seconds

    def _record_inv(session_id, status, request_params, response_body=None, error_message=None, error_details=None):
        inv_file = "tool_invocations.json"
        invocations = _load(inv_file)
        now_iso = _dt_dump(_now())
        row = {
            "id": _new_id("inv"),
            "session_id": session_id,
            "status": status,
            "tool_name": "get_logs",
            "request_params": request_params if isinstance(request_params, dict) else {},
            "response_body": response_body,
            "error_message": error_message,
            "error_details": error_details,
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "related_scene_snapshot_id": None,
            "related_entry_ids": None,
            "file_path": None,
            "paths": None,
            "code": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        invocations.append(row)
        _save(inv_file, invocations)
        return row["id"]

    # Validate
    req = {
        "types": types,
        "count": count,
        "fields": fields,
        "messageContains": messageContains,
        "stackTraceContains": stackTraceContains,
        "timestampAfter": timestampAfter,
        "timestampBefore": timestampBefore,
    }

    allowed_types = {"Log", "Warning", "Error", "Exception"}
    if types is not None:
        if not isinstance(types, list) or any((not isinstance(t, str) or t not in allowed_types) for t in types):
            _record_inv(None, "failed", req, error_message="Validation error", error_details={"field": "types"})
            return _err("VALIDATION_ERROR", "types must be an array of: Log, Warning, Error, Exception.", field="types")

    if count is None:
        count_i = 100
    else:
        if isinstance(count, bool) or not isinstance(count, (int, float)) or int(count) != count:
            _record_inv(None, "failed", req, error_message="Validation error", error_details={"field": "count"})
            return _err("VALIDATION_ERROR", "count must be an integer between 1 and 1000.", field="count")
        count_i = int(count)
        if count_i < 1 or count_i > 1000:
            _record_inv(None, "failed", req, error_message="Validation error", error_details={"field": "count", "min": 1, "max": 1000})
            return _err("VALIDATION_ERROR", "count must be between 1 and 1000.", field="count", min=1, max=1000)

    allowed_fields = {"message", "stackTrace", "logType", "timestamp"}
    if fields is None:
        fields_list = ["message", "logType", "timestamp"]
    else:
        if not isinstance(fields, list) or any((not isinstance(f, str) or f not in allowed_fields) for f in fields):
            _record_inv(None, "failed", req, error_message="Validation error", error_details={"field": "fields"})
            return _err("VALIDATION_ERROR", "fields must be an array of: message, stackTrace, logType, timestamp.", field="fields")
        fields_list = fields

    if messageContains is not None and not isinstance(messageContains, str):
        _record_inv(None, "failed", req, error_message="Validation error", error_details={"field": "messageContains"})
        return _err("VALIDATION_ERROR", "messageContains must be a string.", field="messageContains")
    if stackTraceContains is not None and not isinstance(stackTraceContains, str):
        _record_inv(None, "failed", req, error_message="Validation error", error_details={"field": "stackTraceContains"})
        return _err("VALIDATION_ERROR", "stackTraceContains must be a string.", field="stackTraceContains")

    ts_after = _dt_parse(timestampAfter) if timestampAfter is not None else None
    if timestampAfter is not None and ts_after is None:
        _record_inv(None, "failed", req, error_message="Validation error", error_details={"field": "timestampAfter"})
        return _err("VALIDATION_ERROR", "timestampAfter must be an ISO datetime.", field="timestampAfter")

    ts_before = _dt_parse(timestampBefore) if timestampBefore is not None else None
    if timestampBefore is not None and ts_before is None:
        _record_inv(None, "failed", req, error_message="Validation error", error_details={"field": "timestampBefore"})
        return _err("VALIDATION_ERROR", "timestampBefore must be an ISO datetime.", field="timestampBefore")

    if ts_after and ts_before and ts_after > ts_before:
        _record_inv(None, "failed", req, error_message="Validation error", error_details={"field": "timestampAfter", "rule": "timestampAfter<=timestampBefore"})
        return _err("VALIDATION_ERROR", "timestampAfter must be <= timestampBefore.", field="timestampAfter", rule="timestampAfter<=timestampBefore")

    sessions = _load("unity_editor_sessions.json")
    active, staleness_window_seconds = _pick_active_session(sessions, 30)
    if not active:
        _record_inv(None, "failed", req, error_message="No active Unity Editor connection", error_details={"staleness_window_seconds": staleness_window_seconds})
        return _err("UNAUTHORIZED", "No active Unity Editor connection", staleness_window_seconds=staleness_window_seconds)

    session_id = active.get("id")

    logs = _load("editor_logs.json")
    rows = []
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("session_id") != session_id:
            continue
        if types is not None and r.get("log_type") not in types:
            continue
        if messageContains is not None:
            msg = r.get("message") or ""
            if messageContains not in msg:
                continue
        if stackTraceContains is not None:
            st = r.get("stack_trace") or ""
            if stackTraceContains not in st:
                continue
        ts = _dt_parse(r.get("timestamp"))
        if ts is None:
            continue
        if ts_after and ts < ts_after:
            continue
        if ts_before and ts > ts_before:
            continue
        rows.append((ts, r))

    def _seq(v):
        if isinstance(v, bool) or v is None:
            return -1
        if isinstance(v, int):
            return v
        if isinstance(v, float) and int(v) == v:
            return int(v)
        return -1

    rows.sort(key=lambda tr: (tr[0], _seq(tr[1].get("sequence_no"))), reverse=True)
    selected = []
    for _, r in rows[:count_i]:
        out = {}
        for f in fields_list:
            if f == "message":
                out["message"] = r.get("message")
            elif f == "stackTrace":
                out["stackTrace"] = r.get("stack_trace")
            elif f == "logType":
                out["logType"] = r.get("log_type")
            elif f == "timestamp":
                out["timestamp"] = r.get("timestamp")
        selected.append(out)

    resp = {"sessionId": session_id, "count": len(selected), "logs": selected}
    _record_inv(session_id, "succeeded", req, response_body=resp)
    return resp

