    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0289000" if __import__("os").path.isdir("./environment_mix/0289000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _dt_parse(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            d = datetime.datetime.fromisoformat(s)
            return d if d.tzinfo else d.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _dt_dump(d):
        if d is None:
            return None
        if isinstance(d, str):
            return d
        if not isinstance(d, datetime.datetime):
            return None
        dd = d.astimezone(datetime.timezone.utc)
        return dd.isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _record_inv(session_id, status, response_body=None, error_message=None, error_details=None):
        inv_file = "tool_invocations.json"
        invocations = _load(inv_file)
        now_iso = _dt_dump(_now())
        row = {
            "id": _new_id("inv"),
            "session_id": session_id,
            "status": status,
            "tool_name": "verify_connection",
            "request_params": {},
            "response_body": response_body,
            "error_message": error_message,
            "error_details": error_details,
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
