    best_hb = None
    for s in sessions:
        if s.get("status") != "connected":
            continue
        hb = _dt_parse(s.get("last_heartbeat_at"))
        if hb is None or hb > now:
            continue
        if (now - hb).total_seconds() > STALE_SECONDS:
            continue
        if best is None or (best_hb is not None and hb > best_hb) or (best_hb is None and hb is not None):
            best = s
            best_hb = hb

    if not best:
        # Business rule: return failure and log tool_invocations with status='failed' (not NOT_FOUND)
