    resp = {
        "connected": True,
        "staleness_window_seconds": STALE_SECONDS,
        "session": {
            "id": best.get("id"),
            "connection_name": best.get("connection_name"),
            "unity_version": best.get("unity_version"),
            "project_path": best.get("project_path"),
            "assets_root_path": best.get("assets_root_path"),
            "project_guid": best.get("project_guid"),
            "last_heartbeat_at": best.get("last_heartbeat_at"),
        },
    }
    _record_inv(best.get("id"), "succeeded", response_body={"connected": True, "session_id": best.get("id")})
    return resp

