        if d is None:
            return None
        if isinstance(d, str):
            return d
        if not isinstance(d, datetime.datetime):
            return None
        return d.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _pick_active_session(sessions, staleness_window_seconds=30):
        now = _now()
        best = None
        best_hb = None
        for s in sessions:
            if not isinstance(s, dict):
                continue
