                age = 0
            if age <= staleness_window_seconds:
                if best is None or hb > best_hb:
                    best = s
                    best_hb = hb
        return best, staleness_window_seconds

    def _record_inv(session_id, status, request_params, response_body=None, error_message=None, error_details=None, file_path=None, related_entry_ids=None):
        inv_file = "tool_invocations.json"
        invocations = _load(inv_file)
        now_iso = _dt_dump(_now())
        row = {
            "id": _new_id("inv"),
            "session_id": session_id,
            "status": status,
            "tool_name": "read_file",
            "request_params": request_params if isinstance(request_params, dict) else {},
            "response_body": response_body,
            "error_message": error_message,
            "error_details": error_details,
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "related_scene_snapshot_id": None,
            "related_entry_ids": related_entry_ids,
            "file_path": file_path,
            "paths": None,
            "code": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        invocations.append(row)
        _save(inv_file, invocations)
        return row["id"]

    # Validate
    if not isinstance(path, str):
        _record_inv(None, "failed", {"path": path}, error_message="Validation error", error_details={"field": "path"})
        return _err("VALIDATION_ERROR", "path must be a string.", field="path")
    if path == "":
        # tool schema allows empty meaning Assets folder, but this tool is read_file (file); treat empty as invalid for file read
        _record_inv(None, "failed", {"path": path}, error_message="Validation error", error_details={"field": "path"})
        return _err("VALIDATION_ERROR", "path must be a non-empty string for read_file.", field="path")

    sessions = _load("unity_editor_sessions.json")
    active, staleness_window_seconds = _pick_active_session(sessions, 30)
    if not active:
        _record_inv(None, "failed", {"path": path}, error_message="No active Unity Editor connection", error_details={"staleness_window_seconds": staleness_window_seconds}, file_path=path)
        return _err("UNAUTHORIZED", "No active Unity Editor connection", staleness_window_seconds=staleness_window_seconds)

    session_id = active.get("id")
    assets_root = active.get("assets_root_path")

    if not isinstance(assets_root, str) or not assets_root.endswith("/Assets"):
        # Cannot safely resolve filesystem
        _record_inv(session_id, "failed", {"path": path}, error_message="Assets root not configured for session", error_details={"rule": "assets_root_path like '%/Assets'"}, file_path=path)
        return _err("UNAUTHORIZED", "Active session has no valid assets_root_path configured.", rule="assets_root_path like '%/Assets'")

    def _normalize_rel(p):
        p = p.replace("\\", "/").strip()
        while p.startswith("./"):
            p = p[2:]
        if p.startswith("/"):
            p = p[1:]
        # collapse // and .
        parts = []
        for seg in p.split("/"):
            if seg in ("", "."):
                continue
            if seg == "..":
                return None
            parts.append(seg)
        return "/".join(parts)

    # Resolve absolute vs relative
    if os.path.isabs(path) or (len(path) > 2 and path[1] == ":" and (path[2:3] == "\\" or path[2:3] == "/")):
        abs_path = os.path.normpath(path)
    else:
        rel = _normalize_rel(path)
        if rel is None:
            _record_inv(session_id, "failed", {"path": path}, error_message="Invalid path traversal", error_details={"rule": "no .. segments"}, file_path=path)
            return _err("VALIDATION_ERROR", "path must not contain '..' segments.", rule="no .. segments")
        abs_path = os.path.normpath(os.path.join(assets_root, rel))

    # Enforce under Assets root
    assets_norm = os.path.normpath(assets_root)
    try:
        common = os.path.commonpath([assets_norm, abs_path])
    except Exception:
        common = None
    if common != assets_norm:
        _record_inv(session_id, "failed", {"path": path}, error_message="Assets root violation", error_details={"rule": "must be within Assets root"}, file_path=path)
        return _err("UNAUTHORIZED", "Path is outside the project's Assets root.", rule="must be within Assets root")

    # Read file
    if not os.path.exists(abs_path) or not os.path.isfile(abs_path):
        _record_inv(session_id, "failed", {"path": path}, error_message="File not found", error_details={"resolved_path": abs_path}, file_path=path)
        return _err("NOT_FOUND", "File does not exist.", path=path)

    try:
        with open(abs_path, "rb") as f:
            data = f.read()
    except OSError as e:
        _record_inv(session_id, "failed", {"path": path}, error_message="Failed to read file", error_details={"os_error": str(e)}, file_path=path)
        return _err("NOT_FOUND", "Unable to read file.", path=path)

    # Try decode as utf-8, else return base64-ish? Tool expects string; return latin-1 fallback to preserve bytes.
    try:
        text = data.decode("utf-8")
        encoding = "utf-8"
    except UnicodeDecodeError:
        text = data.decode("latin-1")
        encoding = "latin-1"

    # Find project entry id if exists
    rel_under_assets = os.path.relpath(abs_path, assets_norm).replace("\\", "/")
    rel_norm = _normalize_rel(rel_under_assets) or rel_under_assets
    entries = _load("project_entries.json")
    entry_id = None
    for e in entries:
        if isinstance(e, dict) and e.get("session_id") == session_id and e.get("path") == rel_norm:
            entry_id = e.get("id")
            break

    resp = {"path": rel_norm, "encoding": encoding, "content": text}
    _record_inv(session_id, "succeeded", {"path": path}, response_body=resp, file_path=rel_norm, related_entry_ids=[entry_id] if entry_id else None)
    return resp

