            hb = _dt_parse(s.get("last_heartbeat_at"))
            if hb is None:
                continue
            age = (now - hb).total_seconds()
            if age < 0:
                age = 0
            if age <= staleness_window_seconds:
                if best is None or hb > best_hb:
                    best = s
                    best_hb = hb
        return best, staleness_window_seconds

    def _record_inv(session_id, status, request_params, response_body=None, error_message=None, error_details=None, norm_paths=None, related_entry_ids=None):
        inv_file = "tool_invocations.json"
        invocations = _load(inv_file)
        now_iso = _dt_dump(_now())
        row = {
            "id": _new_id("inv"),
            "session_id": session_id,
            "status": status,
            "tool_name": "read_multiple_files",
            "request_params": request_params if isinstance(request_params, dict) else {},
            "response_body": response_body,
            "error_message": error_message,
            "error_details": error_details,
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "related_scene_snapshot_id": None,
            "related_entry_ids": related_entry_ids,
            "file_path": None,
            "paths": norm_paths,
            "code": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        invocations.append(row)
        _save(inv_file, invocations)
        return row["id"]

    # Validate
    if not isinstance(paths, list) or len(paths) < 1:
        _record_inv(None, "failed", {"paths": paths}, error_message="Validation error", error_details={"field": "paths"})
        return _err("VALIDATION_ERROR", "paths must be a non-empty array of strings.", field="paths")
    if len(paths) > 1000:
        _record_inv(None, "failed", {"paths": paths[:5]}, error_message="Validation error", error_details={"field": "paths", "maxItems": 1000})
        return _err("VALIDATION_ERROR", "paths must contain between 1 and 1000 items.", field="paths", maxItems=1000)
    if any((not isinstance(p, str) or p == "") for p in paths):
        _record_inv(None, "failed", {"paths": paths}, error_message="Validation error", error_details={"field": "paths"})
        return _err("VALIDATION_ERROR", "Each path must be a non-empty string.", field="paths")

    sessions = _load("unity_editor_sessions.json")
    active, staleness_window_seconds = _pick_active_session(sessions, 30)
    if not active:
        _record_inv(None, "failed", {"paths": paths}, error_message="No active Unity Editor connection", error_details={"staleness_window_seconds": staleness_window_seconds})
        return _err("UNAUTHORIZED", "No active Unity Editor connection", staleness_window_seconds=staleness_window_seconds)

    session_id = active.get("id")
    assets_root = active.get("assets_root_path")
    if not isinstance(assets_root, str) or not assets_root.endswith("/Assets"):
        _record_inv(session_id, "failed", {"paths": paths}, error_message="Assets root not configured for session", error_details={"rule": "assets_root_path like '%/Assets'"})
        return _err("UNAUTHORIZED", "Active session has no valid assets_root_path configured.", rule="assets_root_path like '%/Assets'")

    def _normalize_rel(p):
        p = p.replace("\\", "/").strip()
        while p.startswith("./"):
            p = p[2:]
        if p.startswith("/"):
            p = p[1:]
        parts = []
        for seg in p.split("/"):
            if seg in ("", "."):
                continue
            if seg == "..":
                return None
            parts.append(seg)
        return "/".join(parts)

    assets_norm = os.path.normpath(assets_root)
    entries = _load("project_entries.json")
    entry_map = {}
    for e in entries:
        if isinstance(e, dict) and e.get("session_id") == session_id and isinstance(e.get("path"), str):
            entry_map[e["path"]] = e.get("id")

    results = []
    norm_paths = []
    related_ids = []
    any_missing = False
    for p in paths:
        if os.path.isabs(p) or (len(p) > 2 and p[1] == ":" and (p[2:3] == "\\" or p[2:3] == "/")):
            abs_path = os.path.normpath(p)
        else:
            rel = _normalize_rel(p)
            if rel is None:
                _record_inv(session_id, "failed", {"paths": paths}, error_message="Invalid path traversal", error_details={"rule": "no .. segments"})
                return _err("VALIDATION_ERROR", "paths must not contain '..' segments.", rule="no .. segments")
            abs_path = os.path.normpath(os.path.join(assets_root, rel))

        try:
            common = os.path.commonpath([assets_norm, abs_path])
        except Exception:
            common = None
        if common != assets_norm:
            _record_inv(session_id, "failed", {"paths": paths}, error_message="Assets root violation", error_details={"rule": "must be within Assets root"})
            return _err("UNAUTHORIZED", "One or more paths are outside the project's Assets root.", rule="must be within Assets root")

        rel_under = os.path.relpath(abs_path, assets_norm).replace("\\", "/")
        rel_norm = _normalize_rel(rel_under) or rel_under
        norm_paths.append(rel_norm)

        if not os.path.exists(abs_path) or not os.path.isfile(abs_path):
            any_missing = True
            results.append({"path": rel_norm, "found": False, "content": None})
            continue

        try:
            with open(abs_path, "rb") as f:
                data = f.read()
        except OSError:
            any_missing = True
            results.append({"path": rel_norm, "found": False, "content": None})
            continue

        try:
            text = data.decode("utf-8")
            encoding = "utf-8"
        except UnicodeDecodeError:
            text = data.decode("latin-1")
            encoding = "latin-1"
        results.append({"path": rel_norm, "found": True, "encoding": encoding, "content": text})
        eid = entry_map.get(rel_norm)
        if eid:
            related_ids.append(eid)

    if any_missing:
        # Tool description says NOT_FOUND if any requested file missing
        _record_inv(session_id, "failed", {"paths": paths}, error_message="One or more files not found", error_details={"results": results}, norm_paths=norm_paths, related_entry_ids=related_ids or None)
        return _err("NOT_FOUND", "One or more requested files do not exist.", results=results)

    resp = {"paths": norm_paths, "results": results}
    _record_inv(session_id, "succeeded", {"paths": paths}, response_body=resp, norm_paths=norm_paths, related_entry_ids=related_ids or None)
    return resp

def write_file(path, content, **_extra):
    import json, os, datetime, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0289000" if __import__("os").path.isdir("./environment_mix/0289000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = datetime.datetime.utcnow()

    # ---- helpers ----
    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(dt):
        if dt is None:
            return None
        if isinstance(dt, (int, float)):
            return None
        if not isinstance(dt, str):
            return None
        s = dt.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_tool_invocation(session_id, tool_name, request_params, **fields):
        invocations = _load("tool_invocations.json")
        now = _now_iso()
        new_id = "tin_" + hashlib.sha256((now + "|" + tool_name + "|" + (session_id or "") + "|" + str(len(invocations) + 1)).encode("utf-8")).hexdigest()[:24]
        row = {
            "id": new_id,
            "session_id": session_id,
            "status": "received",
            "tool_name": tool_name,
            "request_params": request_params,
            "response_body": None,
            "error_message": None,
            "error_details": None,
            "duration_ms": None,
            "related_scene_snapshot_id": None,
            "related_entry_ids": None,
            "file_path": fields.get("file_path"),
            "paths": fields.get("paths"),
            "code": fields.get("code"),
            "created_at": now,
            "updated_at": now,
        }
        invocations.append(row)
        _save("tool_invocations.json", invocations)
        return row["id"]

    def _finalize_tool_invocation(inv_id, status, response_body=None, error_message=None, error_details=None, related_entry_ids=None):
        invocations = _load("tool_invocations.json")
        now = _now_iso()
        end = datetime.datetime.utcnow()
        duration_ms = int(max(0, (end - start).total_seconds() * 1000))
        updated = False
        for r in invocations:
            if r.get("id") == inv_id:
                # lifecycle transitions
                cur = r.get("status")
                allowed = {
                    "received": ["running", "cancelled", "failed"],
                    "running": ["succeeded", "failed", "cancelled"],
                    "succeeded": [],
                    "failed": [],
                    "cancelled": []
                }
                # we will do received -> running -> final
                if cur == "received":
                    r["status"] = "running"
                    r["updated_at"] = now
                    cur = "running"
                if status not in allowed.get(cur, []):
                    # if cannot transition, force failed with details
                    r["status"] = "failed"
                    r["error_message"] = "Invalid invocation status transition"
                    r["error_details"] = {"from": cur, "to": status}
                else:
                    r["status"] = status
                    r["response_body"] = response_body
                    r["error_message"] = error_message
                    r["error_details"] = error_details
                    r["related_entry_ids"] = related_entry_ids
                r["duration_ms"] = duration_ms
                r["updated_at"] = now
                updated = True
                break
        if updated:
            _save("tool_invocations.json", invocations)

    def _active_session():
        sessions = _load("unity_editor_sessions.json")
        now = datetime.datetime.utcnow()
        # staleness window: 30s
        best = None
        best_hb = None
        for s in sessions:
            if s.get("status") != "connected":
                continue
            hb = _parse_iso(s.get("last_heartbeat_at"))
            if hb is None:
                continue
            # treat naive as UTC if provided; fromisoformat returns aware maybe
            if hb.tzinfo is not None:
                hb_utc = hb.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            else:
                hb_utc = hb
            if (now - hb_utc).total_seconds() <= 30:
                if best is None or hb_utc > best_hb:
                    best = s
                    best_hb = hb_utc
        return best

    def _norm_rel_assets_path(p):
        # returns normalized relative path under Assets ('' allowed)
        if not isinstance(p, str):
            return None
        p = p.strip()
        if p == "":
            return ""  # Assets root
        p = p.replace("\\", "/")
        # If absolute, we keep it to resolve later
        if os.path.isabs(p):
            return p
        # remove leading "./"
        while p.startswith("./"):
            p = p[2:]
        # disallow leading slash
        if p.startswith("/"):
            return None
        # normalize segments; disallow '..'
        segs = []
        for part in p.split("/"):
            if part in ("", "."):
                continue
            if part == "..":
                return None
            segs.append(part)
        return "/".join(segs)

    def _resolve_to_assets_relative_and_abs(active, in_path):
        # Accept absolute or relative; must end up within assets_root_path
        assets_root = active.get("assets_root_path")
        proj_path = active.get("project_path")
        if not isinstance(assets_root, str) or not assets_root:
            # try derive
            if isinstance(proj_path, str) and proj_path:
                assets_root = os.path.join(proj_path, "Assets")
            else:
                assets_root = None

        if not assets_root:
            return None, None, "Active session missing assets_root_path"

        assets_root_norm = os.path.normpath(assets_root)

        p = _norm_rel_assets_path(in_path)
        if p is None:
            return None, None, "Invalid path (malformed or contains '..')"

        if os.path.isabs(p):
            abs_path = os.path.normpath(p)
            # ensure within assets_root
            try:
                common = os.path.commonpath([assets_root_norm, abs_path])
            except Exception:
                return None, None, "Invalid absolute path"
            if common != assets_root_norm:
                return None, None, "Resolved path is outside Assets root"
            rel = os.path.relpath(abs_path, assets_root_norm).replace("\\", "/")
            if rel == ".":
                rel = ""
            # Validate rel doesn't include '..'
            if _norm_rel_assets_path(rel) is None:
                return None, None, "Invalid resolved relative path"
            return rel, abs_path, None
        else:
            rel = p
            abs_path = os.path.normpath(os.path.join(assets_root_norm, rel))
            try:
                common = os.path.commonpath([assets_root_norm, abs_path])
            except Exception:
                return None, None, "Invalid path"
            if common != assets_root_norm:
                return None, None, "Resolved path is outside Assets root"
            return rel, abs_path, None

    def _upsert_directory_entries(entries, session_id, dir_rel_path):
        # Ensure directories along dir_rel_path exist as present directory entries
        # dir_rel_path '' => Assets root, which is represented with path ''
        now = _now_iso()
        touched_ids = []
        # Build chain: '' (root) then each segment accumulated
        chain = [""]
        if dir_rel_path:
            parts = [p for p in dir_rel_path.split("/") if p]
            acc = ""
            for part in parts:
                acc = part if acc == "" else acc + "/" + part
                chain.append(acc)
        # Create/update each as directory (except root also directory)
        idx = {(e.get("session_id"), e.get("path")): e for e in entries}
        for i, dpath in enumerate(chain):
            existing = idx.get((session_id, dpath))
            parent = None
            name = "Assets" if dpath == "" else dpath.split("/")[-1]
            parent_path = None if dpath == "" else ("/".join(dpath.split("/")[:-1]) or "")
            if dpath != "":
                parent_path = parent_path
            if existing:
                changed = False
                # if exists but is file, conflict? keep file? For parent directories, must be directory.
                if existing.get("entry_type") != "directory":
                    return None, _err("CONFLICT", "Parent path exists as a file", path=dpath)
                if existing.get("status") != "present":
                    # transition allowed ignored->present or deleted->present
                    existing["status"] = "present"
                    changed = True
                if existing.get("name") != name:
                    existing["name"] = name
                    changed = True
                if existing.get("parent_path") != (None if dpath == "" else parent_path):
                    existing["parent_path"] = (None if dpath == "" else parent_path)
                    changed = True
                if existing.get("extension") is not None:
                    existing["extension"] = None
                    changed = True
                if existing.get("size_bytes") is not None:
                    existing["size_bytes"] = None
                    changed = True
                if existing.get("is_text") is not False:
                    # directories: is_text false
                    existing["is_text"] = False
                    changed = True
                if changed:
                    existing["updated_at"] = now
                touched_ids.append(existing.get("id"))
            else:
                new_id = "pe_" + hashlib.sha256((now + "|dir|" + session_id + "|" + dpath).encode("utf-8")).hexdigest()[:24]
                row = {
                    "id": new_id,
                    "session_id": session_id,
                    "status": "present",
                    "path": dpath,
                    "absolute_path": None,
                    "entry_type": "directory",
                    "parent_path": None if dpath == "" else parent_path,
                    "name": name,
                    "extension": None,
                    "size_bytes": None,
                    "content_hash_sha256": None,
                    "last_modified_at": None,
                    "asset_type": None,
                    "is_text": False,
                    "created_at": now,
                    "updated_at": now
                }
                entries.append(row)
                idx[(session_id, dpath)] = row
                touched_ids.append(new_id)
        return touched_ids, None

    # ---- validate inputs ----
    if not isinstance(path, str):
        # record call without session if possible
        inv_id = _ensure_tool_invocation(session_id="", tool_name="write_file", request_params={"path": path, "content": content}, file_path=None)
        _finalize_tool_invocation(inv_id, "failed", error_message="Validation error", error_details={"field": "path", "reason": "must be string"})
        return _err("VALIDATION_ERROR", "path must be a string")
    if not isinstance(content, str):
        inv_id = _ensure_tool_invocation(session_id="", tool_name="write_file", request_params={"path": path, "content": content}, file_path=None)
        _finalize_tool_invocation(inv_id, "failed", error_message="Validation error", error_details={"field": "content", "reason": "must be string"})
        return _err("VALIDATION_ERROR", "content must be a string")

    active = _active_session()
    if not active:
        inv_id = _ensure_tool_invocation(session_id="", tool_name="write_file", request_params={"path": path, "content": content}, file_path=None)
        _finalize_tool_invocation(inv_id, "failed", error_message="No active connected Unity session")
        return _err("UNAUTHORIZED", "No active connected Unity session")

    rel, abs_path, perr = _resolve_to_assets_relative_and_abs(active, path)
    inv_id = _ensure_tool_invocation(session_id=active.get("id"), tool_name="write_file", request_params={"path": path, "content": content}, file_path=rel if isinstance(rel, str) else None)
    if perr:
        _finalize_tool_invocation(inv_id, "failed", error_message=perr, error_details={"path": path})
        return _err("VALIDATION_ERROR", perr)

    if rel == "":
        _finalize_tool_invocation(inv_id, "failed", error_message="Path must be a file under Assets, not the Assets root", error_details={"path": path})
        return _err("VALIDATION_ERROR", "Path must point to a file under Assets (non-empty)")

    if ".." in rel.split("/"):
        _finalize_tool_invocation(inv_id, "failed", error_message="Invalid path", error_details={"path": rel})
        return _err("VALIDATION_ERROR", "Invalid path")

    # Ensure Assets suffix constraint for session assets_root_path when set
    assets_root_path = active.get("assets_root_path")
    if isinstance(assets_root_path, str) and assets_root_path and not assets_root_path.replace("\\", "/").endswith("/Assets"):
        _finalize_tool_invocation(inv_id, "failed", error_message="Active session assets_root_path is invalid", error_details={"assets_root_path": assets_root_path})
        return _err("CONFLICT", "Active session assets_root_path is invalid (must end with /Assets)")

    # ---- perform write ----
    entries = _load("project_entries.json")
    session_id = active.get("id")
    if not isinstance(session_id, str) or not session_id:
        _finalize_tool_invocation(inv_id, "failed", error_message="Active session missing id")
        return _err("CONFLICT", "Active session missing id")

    # Create parent dirs in index
    parent_dir = "/".join(rel.split("/")[:-1]) or ""
    touched_dir_ids, derr = _upsert_directory_entries(entries, session_id, parent_dir)
    if derr:
        _finalize_tool_invocation(inv_id, "failed", error_message=derr["error"]["message"], error_details=derr["error"])
        return derr

    # Write to disk
    try:
        os.makedirs(os.path.dirname(abs_path), exist_ok=True)
        with open(abs_path, "w", encoding="utf-8") as f:
            f.write(content)
    except Exception as e:
        _finalize_tool_invocation(inv_id, "failed", error_message="Failed to write file", error_details={"exception": str(e), "abs_path": abs_path})
        return _err("CONFLICT", "Failed to write file", details=str(e))

    # Upsert file entry
    now = _now_iso()
    content_bytes = content.encode("utf-8")
    size_bytes = len(content_bytes)
    sha = hashlib.sha256(content_bytes).hexdigest()

    # locate existing row by unique(session_id, path)
    existing = None
    for e in entries:
        if e.get("session_id") == session_id and e.get("path") == rel:
            existing = e
            break

    related_ids = []
    if touched_dir_ids:
        related_ids.extend([i for i in touched_dir_ids if isinstance(i, str)])
    if existing:
        # validate entry_type and update
        existing["entry_type"] = "file"
        # status transition to present from any state
        existing["status"] = "present"
        existing["name"] = rel.split("/")[-1]
        existing["parent_path"] = parent_dir if parent_dir != "" else ""
        # extension
        base = existing["name"]
        ext = None
        if "." in base and not base.startswith("."):
            ext = base.split(".")[-1].lower()
        existing["extension"] = ext
        existing["size_bytes"] = size_bytes
        existing["content_hash_sha256"] = sha
        existing["last_modified_at"] = now
        # is_text: preserve if already present, else guess by extension
        if not isinstance(existing.get("is_text"), bool):
            existing["is_text"] = (ext in ("cs", "shader", "txt", "json", "xml", "yaml", "yml", "md", "asmdef", "cginc", "compute", "uss", "uxml", "prefs", "asset", "meta"))
        existing["updated_at"] = now
        related_ids.append(existing.get("id"))
    else:
        new_id = "pe_" + hashlib.sha256((now + "|file|" + session_id + "|" + rel).encode("utf-8")).hexdigest()[:24]
        name = rel.split("/")[-1]
        ext = None
        if "." in name and not name.startswith("."):
            ext = name.split(".")[-1].lower()
        row = {
            "id": new_id,
            "session_id": session_id,
            "status": "present",
            "path": rel,
            "absolute_path": None,
            "entry_type": "file",
            "parent_path": parent_dir if parent_dir != "" else "",
            "name": name,
            "extension": ext,
            "size_bytes": size_bytes,
            "content_hash_sha256": sha,
            "last_modified_at": now,
            "asset_type": None,
            "is_text": (ext in ("cs", "shader", "txt", "json", "xml", "yaml", "yml", "md", "asmdef", "cginc", "compute", "uss", "uxml", "prefs", "asset", "meta")),
            "created_at": now,
            "updated_at": now
        }
        entries.append(row)
        related_ids.append(new_id)

    _save("project_entries.json", entries)

    resp = {
        "path": rel,
        "bytes_written": size_bytes,
        "content_hash_sha256": sha,
        "last_modified_at": now
    }
    _finalize_tool_invocation(inv_id, "succeeded", response_body=resp, related_entry_ids=related_ids)
    return resp

def edit_file(path, edits, dryRun=None, **_extra):
    import json, os, datetime, time, uuid, difflib, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0289000" if __import__("os").path.isdir("./environment_mix/0289000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _dt_parse(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            d = datetime.datetime.fromisoformat(s)
            return d if d.tzinfo else d.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _dt_dump(d):
        if d is None:
            return None
        if isinstance(d, str):
            return d
        if not isinstance(d, datetime.datetime):
            return None
        return d.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _pick_active_session(sessions, staleness_window_seconds=30):
        now = _now()
        best = None
        best_hb = None
        for s in sessions:
            if not isinstance(s, dict):
                continue
            if s.get("status") != "connected":
                continue
            hb = _dt_parse(s.get("last_heartbeat_at"))
            if hb is None:
                continue
            age = (now - hb).total_seconds()
            if age < 0:
                age = 0
            if age <= staleness_window_seconds:
                if best is None or hb > best_hb:
                    best = s
                    best_hb = hb
        return best, staleness_window_seconds

    def _record_inv(session_id, status, request_params, response_body=None, error_message=None, error_details=None, file_path=None, related_entry_ids=None):
        invocations = _load("tool_invocations.json")
        now_dt = _now()
        row = {
            "id": _new_id("unity_inv"),
            "session_id": session_id,
            "status": status,
            "tool_name": "edit_file",
            "request_params": request_params if isinstance(request_params, dict) else {},
            "response_body": response_body,
            "error_message": error_message,
            "error_details": error_details,
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "related_scene_snapshot_id": None,
            "related_entry_ids": related_entry_ids,
            "file_path": file_path,
            "paths": None,
            "code": None,
            "created_at": _dt_dump(now_dt),
            "updated_at": _dt_dump(now_dt),
        }
        invocations.append(row)
        _save("tool_invocations.json", invocations)
        return row

    def _norm_rel_assets_path(p):
        if not isinstance(p, str):
            return None, "path must be a string"
        p = p.strip()
        if p == "":
            # edit_file expects a file; empty path isn't valid for editing
            return "", None
        p2 = p.replace("\\", "/")
        # remove leading "Assets/" if provided
        if p2.startswith("Assets/"):
            p2 = p2[len("Assets/"):]
        if p2 == "Assets":
            p2 = ""
        # disallow traversal
        parts = [x for x in p2.split("/") if x not in ["", "."]]
        for seg in parts:
            if seg == "..":
                return None, "path must not contain '..' segments after normalization"
        return "/".join(parts), None

    def _sha256_text(s):
        h = hashlib.sha256()
        h.update(s.encode("utf-8"))
        return h.hexdigest()

    # Validate inputs
    if dryRun is None:
        dryRun = False
    if not isinstance(dryRun, bool):
        sessions = _load("unity_editor_sessions.json")
        active, _ = _pick_active_session(sessions)
        sid = active.get("id") if active else (sessions[0].get("id") if sessions and isinstance(sessions[0], dict) else "unknown_session")
        _record_inv(sid, "failed", {"path": path, "edits": edits, "dryRun": dryRun},
                    error_message="Validation error",
                    error_details=_err("VALIDATION_ERROR", "dryRun must be a boolean.", field="dryRun")["error"])
        return _err("VALIDATION_ERROR", "dryRun must be a boolean.", field="dryRun")

    if not isinstance(edits, list) or len(edits) == 0:
        sessions = _load("unity_editor_sessions.json")
        active, _ = _pick_active_session(sessions)
        sid = active.get("id") if active else (sessions[0].get("id") if sessions and isinstance(sessions[0], dict) else "unknown_session")
        _record_inv(sid, "failed", {"path": path, "edits": edits, "dryRun": dryRun},
                    error_message="Validation error",
                    error_details=_err("VALIDATION_ERROR", "edits must be a non-empty array.", field="edits")["error"])
        return _err("VALIDATION_ERROR", "edits must be a non-empty array.", field="edits")

    for i, e in enumerate(edits):
        if not isinstance(e, dict) or "oldText" not in e or "newText" not in e or not isinstance(e.get("oldText"), str) or not isinstance(e.get("newText"), str):
            sessions = _load("unity_editor_sessions.json")
            active, _ = _pick_active_session(sessions)
            sid = active.get("id") if active else (sessions[0].get("id") if sessions and isinstance(sessions[0], dict) else "unknown_session")
            _record_inv(sid, "failed", {"path": path, "edits": edits, "dryRun": dryRun},
                        error_message="Validation error",
                        error_details=_err("VALIDATION_ERROR", "Each edit must be an object with string oldText and newText.", index=i)["error"])
            return _err("VALIDATION_ERROR", "Each edit must be an object with string oldText and newText.", index=i)

    sessions = _load("unity_editor_sessions.json")
    active, _ = _pick_active_session(sessions)
    if not active:
        sid = sessions[0].get("id") if sessions and isinstance(sessions[0], dict) else "unknown_session"
        _record_inv(sid, "failed", {"path": path, "edits": edits, "dryRun": dryRun},
                    error_message="No active Unity Editor connection",
                    error_details=_err("UNAUTHORIZED", "No active Unity Editor connection (no connected session within staleness window).")["error"])
        return _err("UNAUTHORIZED", "No active Unity Editor connection (no connected session within staleness window).")

    session_id = active.get("id")
    rel_path, perr = _norm_rel_assets_path(path)
    if perr:
        _record_inv(session_id, "failed", {"path": path, "edits": edits, "dryRun": dryRun},
                    error_message="Validation error",
                    error_details=_err("VALIDATION_ERROR", perr, path=path)["error"],
                    file_path=path)
        return _err("VALIDATION_ERROR", perr, path=path)

    # If caller passed an absolute filesystem path, require it is under assets_root_path.
    if isinstance(path, str) and (path.startswith("/") or (len(path) > 1 and path[1] == ":" and (path[2:3] == "\\" or path[2:3] == "/"))):
        assets_root = active.get("assets_root_path")
        if not isinstance(assets_root, str) or assets_root.strip() == "":
            _record_inv(session_id, "failed", {"path": path, "edits": edits, "dryRun": dryRun},
                        error_message="Assets root unknown",
                        error_details=_err("CONFLICT", "Active session does not have assets_root_path; cannot validate absolute path is within Assets.")["error"],
                        file_path=rel_path)
            return _err("CONFLICT", "Active session does not have assets_root_path; cannot validate absolute path is within Assets.")
        ap = os.path.realpath(path)
        ar = os.path.realpath(assets_root)
        try:
            common = os.path.commonpath([ap, ar])
        except Exception:
            common = None
        if common != ar:
            _record_inv(session_id, "failed", {"path": path, "edits": edits, "dryRun": dryRun},
                        error_message="Path outside Assets",
                        error_details=_err("UNAUTHORIZED", "File access is restricted to the active session's Assets root.", path=path, assets_root_path=assets_root)["error"],
                        file_path=rel_path)
            return _err("UNAUTHORIZED", "File access is restricted to the active session's Assets root.", path=path, assets_root_path=assets_root)

    # Find indexed entry; if missing, still allow operation to proceed against disk (realistic) if assets_root_path exists
    entries = _load("project_entries.json")
    entry = None
    for e in entries:
        if isinstance(e, dict) and e.get("session_id") == session_id and e.get("path") == rel_path:
            entry = e
            break

    assets_root_path = active.get("assets_root_path") if isinstance(active, dict) else None
    abs_path = None
    if isinstance(assets_root_path, str) and assets_root_path.strip() != "":
        abs_path = os.path.join(assets_root_path, rel_path) if rel_path != "" else assets_root_path

    if entry:
        if entry.get("entry_type") != "file" or entry.get("status") != "present":
            _record_inv(session_id, "failed", {"path": path, "edits": edits, "dryRun": dryRun},
                        error_message="Not a present file",
                        error_details=_err("CONFLICT", "Path exists in index but is not a present file; edit_file requires entry_type='file' and status='present'.",
                                          path=rel_path, entry_type=entry.get("entry_type"), status=entry.get("status"))["error"],
                        file_path=rel_path,
                        related_entry_ids=[entry.get("id")] if entry.get("id") else None)
            return _err("CONFLICT", "Path exists in index but is not a present file; edit_file requires entry_type='file' and status='present'.",
                        path=rel_path, entry_type=entry.get("entry_type"), status=entry.get("status"))
        if entry.get("is_text") is not True:
            _record_inv(session_id, "failed", {"path": path, "edits": edits, "dryRun": dryRun},
                        error_message="File not text",
                        error_details=_err("CONFLICT", "edit_file is allowed only for text files (project_entries.is_text=true).", path=rel_path)["error"],
                        file_path=rel_path,
                        related_entry_ids=[entry.get("id")] if entry.get("id") else None)
            return _err("CONFLICT", "edit_file is allowed only for text files (project_entries.is_text=true).", path=rel_path)

    # Read file contents from disk when possible; if not possible, fall back to indexed absolute_path only if it points under Assets
    content = None
    if abs_path and os.path.exists(abs_path) and os.path.isfile(abs_path):
        try:
            with open(abs_path, "r", encoding="utf-8") as f:
                content = f.read()
        except UnicodeDecodeError:
            _record_inv(session_id, "failed", {"path": path, "edits": edits, "dryRun": dryRun},
                        error_message="Not a UTF-8 text file",
                        error_details=_err("CONFLICT", "File is not valid UTF-8 text; edit_file requires text content.", path=rel_path)["error"],
                        file_path=rel_path,
                        related_entry_ids=[entry.get("id")] if entry and entry.get("id") else None)
            return _err("CONFLICT", "File is not valid UTF-8 text; edit_file requires text content.", path=rel_path)
        except OSError:
            _record_inv(session_id, "failed", {"path": path, "edits": edits, "dryRun": dryRun},
                        error_message="Unable to read file",
                        error_details=_err("CONFLICT", "Unable to read file from disk.", path=rel_path)["error"],
                        file_path=rel_path,
                        related_entry_ids=[entry.get("id")] if entry and entry.get("id") else None)
            return _err("CONFLICT", "Unable to read file from disk.", path=rel_path)
    else:
        # If we cannot read from disk, we cannot safely apply exact edits.
        # However, do not return NOT_FOUND unless we can establish non-existence.
        if abs_path and not os.path.exists(abs_path):
            _record_inv(session_id, "failed", {"path": path, "edits": edits, "dryRun": dryRun},
                        error_message="File does not exist under Assets",
                        error_details=_err("NOT_FOUND", "File does not exist under the active session's Assets root.", path=rel_path)["error"],
                        file_path=rel_path,
                        related_entry_ids=[entry.get("id")] if entry and entry.get("id") else None)
            return _err("NOT_FOUND", "File does not exist under the active session's Assets root.", path=rel_path)
        _record_inv(session_id, "failed", {"path": path, "edits": edits, "dryRun": dryRun},
                    error_message="Cannot access filesystem",
                    error_details=_err("CONFLICT", "Server cannot access the file contents to apply edits (assets_root_path missing or file not readable).", path=rel_path)["error"],
                    file_path=rel_path,
                    related_entry_ids=[entry.get("id")] if entry and entry.get("id") else None)
        return _err("CONFLICT", "Server cannot access the file contents to apply edits (assets_root_path missing or file not readable).", path=rel_path)

    # Apply edits atomically with exact match requirement
    new_content = content
    missing_edits = []
    for i, e in enumerate(edits):
        oldt = e.get("oldText")
        newt = e.get("newText")
        if oldt not in new_content:
            missing_edits.append({"index": i, "oldText": oldt})
        else:
            new_content = new_content.replace(oldt, newt, 1)
    if missing_edits:
        _record_inv(session_id, "failed", {"path": path, "edits": edits, "dryRun": dryRun},
                    error_message="Edit oldText not found",
                    error_details=_err("VALIDATION_ERROR", "One or more edits' oldText were not found exactly in the current file contents; no changes applied.",
                                      path=rel_path, missingEdits=missing_edits)["error"],
                    file_path=rel_path,
                    related_entry_ids=[entry.get("id")] if entry and entry.get("id") else None)
        return _err("VALIDATION_ERROR", "One or more edits' oldText were not found exactly in the current file contents; no changes applied.",
                    path=rel_path, missingEdits=missing_edits)

    diff_lines = list(difflib.unified_diff(
        content.splitlines(keepends=True),
        new_content.splitlines(keepends=True),
        fromfile=f"a/Assets/{rel_path}",
        tofile=f"b/Assets/{rel_path}",
        lineterm=""
    ))
    diff_text = "\n".join(diff_lines)

    # Dry run: do not persist to disk or project_entries fields
    if dryRun:
        _record_inv(session_id, "succeeded", {"path": path, "edits": edits, "dryRun": dryRun},
                    response_body={"path": rel_path, "dryRun": True, "diff": diff_text},
                    file_path=rel_path,
                    related_entry_ids=[entry.get("id")] if entry and entry.get("id") else None)
        return {"path": rel_path, "dryRun": True, "diff": diff_text}

    # Persist to disk
    try:
        with open(abs_path, "w", encoding="utf-8") as f:
            f.write(new_content)
    except OSError:
        _record_inv(session_id, "failed", {"path": path, "edits": edits, "dryRun": dryRun},
                    error_message="Unable to write file",
                    error_details=_err("CONFLICT", "Unable to write updated file to disk.", path=rel_path)["error"],
                    file_path=rel_path,
                    related_entry_ids=[entry.get("id")] if entry and entry.get("id") else None)
        return _err("CONFLICT", "Unable to write updated file to disk.", path=rel_path)

    # Update (or create) project_entries row
    now_dt = _now()
    size_bytes = len(new_content.encode("utf-8"))
    content_hash = _sha256_text(new_content)
    related_ids = []
    if entry:
        entry["status"] = "present"
        entry["entry_type"] = "file"
        entry["size_bytes"] = size_bytes
        entry["content_hash_sha256"] = content_hash
        entry["last_modified_at"] = _dt_dump(now_dt)
        entry["updated_at"] = _dt_dump(now_dt)
        if "created_at" not in entry or not entry["created_at"]:
            entry["created_at"] = _dt_dump(now_dt)
        related_ids = [entry.get("id")] if entry.get("id") else None
    else:
        # create minimal entry (best-effort)
        name = rel_path.split("/")[-1] if rel_path else ""
        ext = None
        if "." in name and not name.startswith("."):
            ext = name.split(".")[-1].lower()
        parent_path = "/".join(rel_path.split("/")[:-1]) if "/" in rel_path else None
        new_entry = {
            "id": _new_id("unity_ent"),
            "session_id": session_id,
            "status": "present",
            "path": rel_path,
            "absolute_path": None,
            "entry_type": "file",
            "parent_path": parent_path,
            "name": name,
            "extension": ext,
            "size_bytes": size_bytes,
            "content_hash_sha256": content_hash,
            "last_modified_at": _dt_dump(now_dt),
            "asset_type": None,
            "is_text": True,
            "created_at": _dt_dump(now_dt),
            "updated_at": _dt_dump(now_dt),
        }
        entries.append(new_entry)
        related_ids = [new_entry["id"]]

    _save("project_entries.json", entries)

    _record_inv(session_id, "succeeded", {"path": path, "edits": edits, "dryRun": dryRun},
                response_body={"path": rel_path, "dryRun": False, "diff": diff_text, "size_bytes": size_bytes},
                file_path=rel_path,
                related_entry_ids=related_ids)
    return {"path": rel_path, "dryRun": False, "diff": diff_text, "size_bytes": size_bytes}

def list_directory(path, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0289000" if __import__("os").path.isdir("./environment_mix/0289000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _dt_parse(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            d = datetime.datetime.fromisoformat(s)
            return d if d.tzinfo else d.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _dt_dump(d):
        if d is None:
            return None
        if isinstance(d, str):
            return d
        if not isinstance(d, datetime.datetime):
            return None
        return d.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _pick_active_session(sessions, staleness_window_seconds=30):
        now = _now()
        best = None
        best_hb = None
        for s in sessions:
            if not isinstance(s, dict):
                continue
            if s.get("status") != "connected":
                continue
            hb = _dt_parse(s.get("last_heartbeat_at"))
            if hb is None:
                continue
            age = (now - hb).total_seconds()
            if age < 0:
                age = 0
            if age <= staleness_window_seconds:
                if best is None or hb > best_hb:
                    best = s
                    best_hb = hb
        return best, staleness_window_seconds

    def _record_inv(session_id, status, request_params, response_body=None, error_message=None, error_details=None, file_path=None, related_entry_ids=None):
        invocations = _load("tool_invocations.json")
        now_dt = _now()
        row = {
            "id": _new_id("unity_inv"),
            "session_id": session_id,
            "status": status,
            "tool_name": "list_directory",
            "request_params": request_params if isinstance(request_params, dict) else {},
            "response_body": response_body,
            "error_message": error_message,
            "error_details": error_details,
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "related_scene_snapshot_id": None,
            "related_entry_ids": related_entry_ids,
            "file_path": file_path,
            "paths": None,
            "code": None,
            "created_at": _dt_dump(now_dt),
            "updated_at": _dt_dump(now_dt),
        }
        invocations.append(row)
        _save("tool_invocations.json", invocations)
        return row

    def _norm_rel_assets_path(p):
        if not isinstance(p, str):
            return None, "path must be a string"
        p = p.strip()
        if p == "":
            return "", None
        p2 = p.replace("\\", "/")
        if p2.startswith("Assets/"):
            p2 = p2[len("Assets/"):]
        if p2 == "Assets":
            p2 = ""
        parts = [x for x in p2.split("/") if x not in ["", "."]]
        for seg in parts:
            if seg == "..":
                return None, "path must not contain '..' segments after normalization"
        return "/".join(parts), None

    sessions = _load("unity_editor_sessions.json")
    active, _ = _pick_active_session(sessions)
    if not active:
        sid = sessions[0].get("id") if sessions and isinstance(sessions[0], dict) else "unknown_session"
        _record_inv(sid, "failed", {"path": path},
                    error_message="No active Unity Editor connection",
                    error_details=_err("UNAUTHORIZED", "No active Unity Editor connection (no connected session within staleness window).")["error"])
        return _err("UNAUTHORIZED", "No active Unity Editor connection (no connected session within staleness window).")
    session_id = active.get("id")

    rel_path, perr = _norm_rel_assets_path(path)
    if perr:
        _record_inv(session_id, "failed", {"path": path},
                    error_message="Validation error",
                    error_details=_err("VALIDATION_ERROR", perr, path=path)["error"],
                    file_path=path)
        return _err("VALIDATION_ERROR", perr, path=path)

    # Use project_entries index first; if it's sparse, fall back to filesystem when available.
    entries = _load("project_entries.json")
    # Determine whether rel_path is a directory (root "" is directory)
    if rel_path == "":
        is_dir = True
        rel_parent = None
    else:
        found = None
        for e in entries:
            if isinstance(e, dict) and e.get("session_id") == session_id and e.get("path") == rel_path and e.get("status") == "present":
                found = e
                break
        if found:
            if found.get("entry_type") != "directory":
                _record_inv(session_id, "failed", {"path": path},
                            error_message="Not a directory",
                            error_details=_err("CONFLICT", "Path exists but is not a directory.", path=rel_path, entry_type=found.get("entry_type"))["error"],
                            file_path=rel_path,
                            related_entry_ids=[found.get("id")] if found.get("id") else None)
                return _err("CONFLICT", "Path exists but is not a directory.", path=rel_path, entry_type=found.get("entry_type"))
            is_dir = True
        else:
            # Try filesystem
            assets_root = active.get("assets_root_path")
            if isinstance(assets_root, str) and assets_root.strip() != "":
                abs_dir = os.path.join(assets_root, rel_path)
                if os.path.isdir(abs_dir):
                    is_dir = True
                elif os.path.exists(abs_dir):
                    _record_inv(session_id, "failed", {"path": path},
                                error_message="Not a directory",
                                error_details=_err("CONFLICT", "Path exists on disk but is not a directory.", path=rel_path)["error"],
                                file_path=rel_path)
                    return _err("CONFLICT", "Path exists on disk but is not a directory.", path=rel_path)
                else:
                    # Index may still have children even if directory row missing; allow listing from index below.
                    is_dir = True
            else:
                # allow index-based listing even without assets_root_path
                is_dir = True

    # List immediate children from index
    children = []
    related_ids = []
    for e in entries:
        if not isinstance(e, dict):
            continue
        if e.get("session_id") != session_id:
            continue
        if e.get("status") != "present":
            continue
        if rel_path == "":
            if e.get("parent_path") is None:
                children.append(e)
                if e.get("id"):
                    related_ids.append(e["id"])
        else:
            if e.get("parent_path") == rel_path:
                children.append(e)
                if e.get("id"):
                    related_ids.append(e["id"])

    # If index has nothing, try filesystem for immediate children.
    if not children:
        assets_root = active.get("assets_root_path")
        if isinstance(assets_root, str) and assets_root.strip() != "":
            abs_dir = os.path.join(assets_root, rel_path) if rel_path != "" else assets_root
            if os.path.isdir(abs_dir):
                try:
                    for name in sorted(os.listdir(abs_dir)):
                        if name in [".", ".."]:
                            continue
                        p = os.path.join(abs_dir, name)
                        children.append({
                            "name": name,
                            "entry_type": "directory" if os.path.isdir(p) else "file",
                            "path": (rel_path + "/" + name).strip("/") if rel_path else name,
                        })
                except OSError:
                    _record_inv(session_id, "failed", {"path": path},
                                error_message="Unable to list directory",
                                error_details=_err("CONFLICT", "Unable to list directory contents.", path=rel_path)["error"],
                                file_path=rel_path)
                    return _err("CONFLICT", "Unable to list directory contents.", path=rel_path)

    # Real behavior: listing a directory that exists but is empty returns empty list, not NOT_FOUND.
    out = []
    for c in children:
        if isinstance(c, dict) and "id" in c:
            out.append({
                "name": c.get("name"),
                "path": c.get("path"),
                "entry_type": c.get("entry_type"),
                "status": c.get("status"),
                "extension": c.get("extension"),
                "asset_type": c.get("asset_type"),
            })
        elif isinstance(c, dict):
            out.append({
                "name": c.get("name"),
                "path": c.get("path"),
                "entry_type": c.get("entry_type"),
            })

    _record_inv(session_id, "succeeded", {"path": path},
                response_body={"path": rel_path, "entries": out},
                file_path=rel_path,
                related_entry_ids=related_ids if related_ids else None)
    return {"path": rel_path, "entries": out}

def directory_tree(path, maxDepth=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0289000" if __import__("os").path.isdir("./environment_mix/0289000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _dt_parse(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            d = datetime.datetime.fromisoformat(s)
            return d if d.tzinfo else d.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _dt_dump(d):
        if d is None:
            return None
        if isinstance(d, str):
            return d
        if not isinstance(d, datetime.datetime):
            return None
        return d.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _pick_active_session(sessions, staleness_window_seconds=30):
        now = _now()
        best = None
        best_hb = None
        for s in sessions:
            if not isinstance(s, dict):
                continue
            if s.get("status") != "connected":
                continue
            hb = _dt_parse(s.get("last_heartbeat_at"))
            if hb is None:
                continue
            age = (now - hb).total_seconds()
            if age < 0:
                age = 0
            if age <= staleness_window_seconds:
                if best is None or hb > best_hb:
                    best = s
                    best_hb = hb
        return best, staleness_window_seconds

    def _record_inv(session_id, status, request_params, response_body=None, error_message=None, error_details=None, file_path=None, related_entry_ids=None):
        invocations = _load("tool_invocations.json")
        now_dt = _now()
        row = {
            "id": _new_id("unity_inv"),
            "session_id": session_id,
            "status": status,
            "tool_name": "directory_tree",
            "request_params": request_params if isinstance(request_params, dict) else {},
            "response_body": response_body,
            "error_message": error_message,
            "error_details": error_details,
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "related_scene_snapshot_id": None,
            "related_entry_ids": related_entry_ids,
            "file_path": file_path,
            "paths": None,
            "code": None,
            "created_at": _dt_dump(now_dt),
            "updated_at": _dt_dump(now_dt),
        }
        invocations.append(row)
        _save("tool_invocations.json", invocations)
        return row

    def _norm_rel_assets_path(p):
        if not isinstance(p, str):
            return None, "path must be a string"
        p = p.strip()
        if p == "":
            return "", None
        p2 = p.replace("\\", "/")
        if p2.startswith("Assets/"):
            p2 = p2[len("Assets/"):]
        if p2 == "Assets":
            p2 = ""
        parts = [x for x in p2.split("/") if x not in ["", "."]]
        for seg in parts:
            if seg == "..":
                return None, "path must not contain '..' segments after normalization"
        return "/".join(parts), None

    # Validate maxDepth
    if maxDepth is None:
        maxDepth = 5
    if not isinstance(maxDepth, (int, float)) or isinstance(maxDepth, bool) or int(maxDepth) != maxDepth:
        sessions = _load("unity_editor_sessions.json")
        active, _ = _pick_active_session(sessions)
        sid = active.get("id") if active else (sessions[0].get("id") if sessions and isinstance(sessions[0], dict) else "unknown_session")
        _record_inv(sid, "failed", {"path": path, "maxDepth": maxDepth},
                    error_message="Validation error",
                    error_details=_err("VALIDATION_ERROR", "maxDepth must be an integer.", field="maxDepth")["error"],
                    file_path=path)
        return _err("VALIDATION_ERROR", "maxDepth must be an integer.", field="maxDepth")
    maxDepth = int(maxDepth)
    if maxDepth < -1:
        sessions = _load("unity_editor_sessions.json")
        active, _ = _pick_active_session(sessions)
        sid = active.get("id") if active else (sessions[0].get("id") if sessions and isinstance(sessions[0], dict) else "unknown_session")
        _record_inv(sid, "failed", {"path": path, "maxDepth": maxDepth},
                    error_message="Validation error",
                    error_details=_err("VALIDATION_ERROR", "maxDepth must be >= -1.", field="maxDepth")["error"],
                    file_path=path)
        return _err("VALIDATION_ERROR", "maxDepth must be >= -1.", field="maxDepth")

    sessions = _load("unity_editor_sessions.json")
    active, _ = _pick_active_session(sessions)
    if not active:
        sid = sessions[0].get("id") if sessions and isinstance(sessions[0], dict) else "unknown_session"
        _record_inv(sid, "failed", {"path": path, "maxDepth": maxDepth},
                    error_message="No active Unity Editor connection",
                    error_details=_err("UNAUTHORIZED", "No active Unity Editor connection (no connected session within staleness window).")["error"])
        return _err("UNAUTHORIZED", "No active Unity Editor connection (no connected session within staleness window).")
    session_id = active.get("id")

    rel_path, perr = _norm_rel_assets_path(path)
    if perr:
        _record_inv(session_id, "failed", {"path": path, "maxDepth": maxDepth},
                    error_message="Validation error",
                    error_details=_err("VALIDATION_ERROR", perr, path=path)["error"],
                    file_path=path)
        return _err("VALIDATION_ERROR", perr, path=path)

    entries = _load("project_entries.json")

    # Determine existence and directory-ness (allow sparse index; fall back to filesystem if available).
    def _find_entry(p):
        for e in entries:
            if isinstance(e, dict) and e.get("session_id") == session_id and e.get("path") == p and e.get("status") == "present":
                return e
        return None

    if rel_path == "":
        base_is_dir = True
        base_entry = None
    else:
        base_entry = _find_entry(rel_path)
        if base_entry:
            if base_entry.get("entry_type") != "directory":
                _record_inv(session_id, "failed", {"path": path, "maxDepth": maxDepth},
                            error_message="Not a directory",
                            error_details=_err("CONFLICT", "Path exists but is not a directory.", path=rel_path, entry_type=base_entry.get("entry_type"))["error"],
                            file_path=rel_path,
                            related_entry_ids=[base_entry.get("id")] if base_entry.get("id") else None)
                return _err("CONFLICT", "Path exists but is not a directory.", path=rel_path, entry_type=base_entry.get("entry_type"))
            base_is_dir = True
        else:
            assets_root = active.get("assets_root_path")
            if isinstance(assets_root, str) and assets_root.strip() != "":
                abs_dir = os.path.join(assets_root, rel_path)
                if os.path.isdir(abs_dir):
                    base_is_dir = True
                elif os.path.exists(abs_dir):
                    _record_inv(session_id, "failed", {"path": path, "maxDepth": maxDepth},
                                error_message="Not a directory",
                                error_details=_err("CONFLICT", "Path exists on disk but is not a directory.", path=rel_path)["error"],
                                file_path=rel_path)
                    return _err("CONFLICT", "Path exists on disk but is not a directory.", path=rel_path)
                else:
                    # If we have children indexed under this path, consider it existing as directory.
                    has_child = any(isinstance(e, dict) and e.get("session_id") == session_id and e.get("status") == "present" and e.get("parent_path") == rel_path for e in entries)
                    if not has_child:
                        _record_inv(session_id, "failed", {"path": path, "maxDepth": maxDepth},
                                    error_message="Path not found",
                                    error_details=_err("NOT_FOUND", "Path does not exist (neither on disk under Assets nor in the project index).", path=rel_path)["error"],
                                    file_path=rel_path)
                        return _err("NOT_FOUND", "Path does not exist (neither on disk under Assets nor in the project index).", path=rel_path)
                    base_is_dir = True
            else:
                has_child = any(isinstance(e, dict) and e.get("session_id") == session_id and e.get("status") == "present" and e.get("parent_path") == rel_path for e in entries)
                if not has_child:
                    _record_inv(session_id, "failed", {"path": path, "maxDepth": maxDepth},
                                error_message="Path not found",
                                error_details=_err("NOT_FOUND", "Path does not exist in the project index.", path=rel_path)["error"],
                                file_path=rel_path)
                    return _err("NOT_FOUND", "Path does not exist in the project index.", path=rel_path)
                base_is_dir = True

    # Build a tree from project_entries; if empty, fall back to filesystem traversal.
    INTERNAL_NODE_CAP = 5000
    related_ids = []

    # Build adjacency list for present entries in this session
    children_map = {}
    entry_by_path = {}
    for e in entries:
        if not isinstance(e, dict):
            continue
        if e.get("session_id") != session_id or e.get("status") != "present":
            continue
        p = e.get("path")
        entry_by_path[p] = e
        parent = e.get("parent_path")
        children_map.setdefault(parent, []).append(e)

    def _node_from_entry(e):
        if e.get("id"):
            related_ids.append(e["id"])
        return {
            "name": e.get("name"),
            "path": e.get("path"),
            "entry_type": e.get("entry_type"),
            "children": [] if e.get("entry_type") == "directory" else None
        }

    visited = 0

    def _build_dir_tree(parent_path, depth):
        nonlocal visited
        if visited >= INTERNAL_NODE_CAP:
            return {"truncated": True, "reason": "internal_node_cap", "cap": INTERNAL_NODE_CAP}
        if maxDepth != -1 and depth > maxDepth:
            return {"truncated": True, "reason": "maxDepth", "maxDepth": maxDepth}
        node_entry = entry_by_path.get(parent_path) if parent_path != "" else None
        node = {
            "name": (node_entry.get("name") if node_entry else "Assets"),
            "path": parent_path,
            "entry_type": "directory",
            "children": []
        }
        kids = children_map.get(parent_path if parent_path != "" else None, [])
        # stable order: directories first then files by name
        def _sortkey(e):
            return (0 if e.get("entry_type") == "directory" else 1, (e.get("name") or ""))
        for e in sorted(kids, key=_sortkey):
            if visited >= INTERNAL_NODE_CAP:
                node["children"].append({"truncated": True, "reason": "internal_node_cap", "cap": INTERNAL_NODE_CAP})
                break
            visited += 1
            if e.get("entry_type") == "directory":
                child = _build_dir_tree(e.get("path"), depth + 1)
                # overlay metadata
                if isinstance(child, dict) and child.get("entry_type") == "directory":
                    child["name"] = e.get("name")
                    child["path"] = e.get("path")
                node["children"].append(child)
            else:
                if e.get("id"):
                    related_ids.append(e["id"])
                node["children"].append({
                    "name": e.get("name"),
                    "path": e.get("path"),
                    "entry_type": "file"
                })
        return node

    tree = _build_dir_tree(rel_path, 0)

    # If index provides no children and we can traverse filesystem, do filesystem traversal to match real behavior.
    def _has_any_child(node):
        return isinstance(node, dict) and isinstance(node.get("children"), list) and len(node["children"]) > 0

    if not _has_any_child(tree):
        assets_root = active.get("assets_root_path")
        if isinstance(assets_root, str) and assets_root.strip() != "":
            abs_base = os.path.join(assets_root, rel_path) if rel_path != "" else assets_root
            if os.path.isdir(abs_base):
                visited = 0
                def _fs_tree(abs_dir, rel_dir, depth):
                    nonlocal visited
                    if visited >= INTERNAL_NODE_CAP:
                        return {"name": os.path.basename(rel_dir) if rel_dir else "Assets", "path": rel_dir, "entry_type": "directory",
                                "children": [{"truncated": True, "reason": "internal_node_cap", "cap": INTERNAL_NODE_CAP}]}
                    if maxDepth != -1 and depth > maxDepth:
                        return {"name": os.path.basename(rel_dir) if rel_dir else "Assets", "path": rel_dir, "entry_type": "directory",
                                "children": [{"truncated": True, "reason": "maxDepth", "maxDepth": maxDepth}]}
                    node = {"name": os.path.basename(rel_dir) if rel_dir else "Assets", "path": rel_dir, "entry_type": "directory", "children": []}
                    try:
                        names = sorted(os.listdir(abs_dir))
                    except OSError:
                        return node
                    for name in names:
                        if name in [".", ".."]:
                            continue
                        p = os.path.join(abs_dir, name)
                        child_rel = (rel_dir + "/" + name).strip("/") if rel_dir else name
                        visited += 1
                        if os.path.isdir(p):
                            node["children"].append(_fs_tree(p, child_rel, depth + 1))
                        else:
                            node["children"].append({"name": name, "path": child_rel, "entry_type": "file"})
                        if visited >= INTERNAL_NODE_CAP:
                            node["children"].append({"truncated": True, "reason": "internal_node_cap", "cap": INTERNAL_NODE_CAP})
                            break
                    return node
                tree = _fs_tree(abs_base, rel_path, 0)

    _record_inv(session_id, "succeeded", {"path": path, "maxDepth": maxDepth},
                response_body={"path": rel_path, "tree": tree},
                file_path=rel_path,
                related_entry_ids=related_ids if related_ids else None)
    return {"path": rel_path, "tree": tree}

def search_files(path, pattern, excludePatterns=None, **_extra):
    import json, os, datetime, time, fnmatch, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0289000" if __import__("os").path.isdir("./environment_mix/0289000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    inv_id = None
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{hashlib.sha256(os.urandom(16)).hexdigest()[:16]}"

    def _parse_iso(dt):
        if dt is None:
            return None
        if not isinstance(dt, str):
            return None
        s = dt.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _record_invocation(status, request_params, response_body=None, error_message=None, error_details=None, file_path=None, paths=None, related_entry_ids=None, duration_ms=None):
        nonlocal inv_id
        invocations = _load("tool_invocations.json")
        if inv_id is None:
            inv_id = _new_id("inv")
        row = None
        for r in invocations:
            if r.get("id") == inv_id:
                row = r
                break
        if row is None:
            row = {
                "id": inv_id,
                "session_id": request_params.get("_session_id"),
                "status": "received",
                "tool_name": "search_files",
                "request_params": {k: v for k, v in request_params.items() if k != "_session_id"},
                "response_body": None,
                "error_message": None,
                "error_details": None,
                "duration_ms": None,
                "related_scene_snapshot_id": None,
                "related_entry_ids": None,
                "file_path": None,
                "paths": None,
                "code": None,
                "created_at": now,
                "updated_at": now,
            }
            invocations.append(row)
        # lifecycle transitions: received->running/failed/succeeded
        def _can_trans(a, b):
            trans = {
                "received": ["running", "cancelled", "failed"],
                "running": ["succeeded", "failed", "cancelled"],
                "succeeded": [],
                "failed": [],
                "cancelled": [],
            }
            return b in trans.get(a, [])
        if row["status"] == "received":
            if _can_trans("received", "running"):
                row["status"] = "running"
        row["updated_at"] = now
        # finish status
        if status != "running":
            if _can_trans(row["status"], status):
                row["status"] = status
            else:
                # if already terminal, keep it
                pass
        if response_body is not None:
            row["response_body"] = response_body
        if error_message is not None:
            row["error_message"] = error_message
        if error_details is not None:
            row["error_details"] = error_details
        if duration_ms is not None:
            row["duration_ms"] = duration_ms
        if file_path is not None:
            row["file_path"] = file_path
        if paths is not None:
            row["paths"] = paths
        if related_entry_ids is not None:
            row["related_entry_ids"] = related_entry_ids
        _save("tool_invocations.json", invocations)

    # Validate inputs
    if not isinstance(path, str):
        return _err("VALIDATION_ERROR", "path must be a string")
    if not isinstance(pattern, str) or pattern.strip() == "":
        return _err("VALIDATION_ERROR", "pattern must be a non-empty string")
    if excludePatterns is None:
        excludePatterns = []
    if not isinstance(excludePatterns, list) or any(not isinstance(x, str) for x in excludePatterns):
        return _err("VALIDATION_ERROR", "excludePatterns must be an array of strings")

    # Resolve active connected session (ambient auth)
    sessions = _load("unity_editor_sessions.json")
    def _is_connected_active(s):
        if s.get("status") != "connected":
            return False
        hb = s.get("last_heartbeat_at")
        dt = _parse_iso(hb) if isinstance(hb, str) else None
        if dt is None:
            return False
        age = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - dt.astimezone(datetime.timezone.utc)
        return age.total_seconds() <= 30

    active = None
    for s in sorted(sessions, key=lambda r: (r.get("last_heartbeat_at") or "", r.get("updated_at") or ""), reverse=True):
        if _is_connected_active(s) and isinstance(s.get("assets_root_path"), str) and s.get("assets_root_path").endswith("/Assets"):
            active = s
            break
    if active is None:
        # still record invocation
        _record_invocation(
            "failed",
            {"_session_id": None, "path": path, "pattern": pattern, "excludePatterns": excludePatterns},
            error_message="No active connected Unity Editor session",
            error_details=_err("UNAUTHORIZED", "No active connected Unity Editor session")["error"],
            duration_ms=int((time.time() - t0) * 1000),
        )
        return _err("UNAUTHORIZED", "No active connected Unity Editor session")

    assets_root = active.get("assets_root_path")
    # Normalize search start path
    raw_path = path.strip()
    def _norm_rel_assets(p):
        # return normalized relative path under Assets, "" allowed
        if p == "":
            return ""
        # Convert backslashes
        p = p.replace("\\", "/")
        # Strip leading "Assets/" if provided
        if p == "Assets":
            return ""
        if p.startswith("Assets/"):
            p = p[len("Assets/"):]
        # Reject absolute-looking paths here; those are handled separately
        if p.startswith("/"):
            return None
        # Normalize and reject '..'
        segs = []
        for part in p.split("/"):
            if part in ("", "."):
                continue
            if part == "..":
                return None
            segs.append(part)
        return "/".join(segs)

    def _resolve_to_abs(p):
        # Accept absolute or relative. Must resolve within assets_root.
        if p == "":
            return assets_root, ""
        p2 = p.replace("\\", "/")
        # absolute?
        is_abs = os.path.isabs(p2)
        if is_abs:
            abs_candidate = os.path.normpath(p2)
            # prove within assets_root
            try:
                common = os.path.commonpath([os.path.abspath(abs_candidate), os.path.abspath(assets_root)])
            except Exception:
                return None, None
            if common != os.path.abspath(assets_root):
                return None, None
            rel = os.path.relpath(abs_candidate, assets_root).replace("\\", "/")
            rel = "" if rel == "." else rel
            # validate no '..' after normalization
            rel_norm = _norm_rel_assets(rel)
            if rel_norm is None and rel != "":
                return None, None
            return os.path.join(assets_root, rel_norm) if rel_norm != "" else assets_root, rel_norm or ""
        else:
            rel_norm = _norm_rel_assets(p2)
            if rel_norm is None:
                return None, None
            abs_p = os.path.join(assets_root, rel_norm) if rel_norm != "" else assets_root
            return abs_p, rel_norm

    start_abs, start_rel = _resolve_to_abs(raw_path)
    if start_abs is None:
        _record_invocation(
            "failed",
            {"_session_id": active["id"], "path": path, "pattern": pattern, "excludePatterns": excludePatterns},
            error_message="Path is outside Assets root or malformed",
            error_details=_err("VALIDATION_ERROR", "Path is outside Assets root or malformed")["error"],
            duration_ms=int((time.time() - t0) * 1000),
            file_path=start_rel if isinstance(start_rel, str) else None,
        )
        return _err("VALIDATION_ERROR", "Path is outside Assets root or malformed")

    # Ensure the search root exists (directory) in filesystem OR indexed entries
    entries = _load("project_entries.json")
    sess_id = active["id"]

    def _entry_for(relp):
        for e in entries:
            if e.get("session_id") == sess_id and e.get("path") == relp:
                return e
        return None

    # Determine existence: prefer filesystem
    if not os.path.exists(start_abs):
        # maybe indexed?
        e = _entry_for(start_rel)
        if e is None or e.get("status") != "present":
            _record_invocation(
                "failed",
                {"_session_id": sess_id, "path": path, "pattern": pattern, "excludePatterns": excludePatterns},
                error_message="Search root not found",
                error_details=_err("NOT_FOUND", "No file or directory exists at the given path")["error"],
                duration_ms=int((time.time() - t0) * 1000),
                file_path=start_rel,
            )
            return _err("NOT_FOUND", "No file or directory exists at the given path")

    # Search using indexed project_entries (consistent with server index); cap results
    include_pat = pattern
    exclude_pats = excludePatterns or []
    internal_cap = 10000

    def _name_of(relp):
        if relp == "":
            return "Assets"
        return relp.split("/")[-1]

    matches = []
    touched_ids = []
    base_prefix = (start_rel + "/") if start_rel != "" else ""
    for e in entries:
        if e.get("session_id") != sess_id:
            continue
        pth = e.get("path")
        if not isinstance(pth, str):
            continue
        if start_rel == "":
            in_scope = True
        else:
            in_scope = (pth == start_rel) or pth.startswith(base_prefix)
        if not in_scope:
            continue
        if e.get("status") != "present":
            continue
        nm = _name_of(pth)
        if fnmatch.fnmatchcase(nm, include_pat):
            excluded = False
            for xp in exclude_pats:
                if fnmatch.fnmatchcase(nm, xp):
                    excluded = True
                    break
            if excluded:
                continue
            matches.append({
                "path": pth,
                "name": nm,
                "entry_type": e.get("entry_type"),
                "asset_type": e.get("asset_type"),
            })
            if e.get("id"):
                touched_ids.append(e.get("id"))
