        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    inv_id = None
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{hashlib.sha256(os.urandom(16)).hexdigest()[:16]}"

    def _parse_iso(dt):
        if dt is None:
            return None
        if not isinstance(dt, str):
            return None
        s = dt.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _record_invocation(status, request_params, response_body=None, error_message=None, error_details=None, file_path=None, related_entry_ids=None, duration_ms=None):
        nonlocal inv_id
        invocations = _load("tool_invocations.json")
        if inv_id is None:
            inv_id = _new_id("inv")
        row = None
        for r in invocations:
            if r.get("id") == inv_id:
                row = r
                break
        if row is None:
            row = {
                "id": inv_id,
                "session_id": request_params.get("_session_id"),
                "status": "received",
                "tool_name": "get_file_info",
                "request_params": {k: v for k, v in request_params.items() if k != "_session_id"},
                "response_body": None,
                "error_message": None,
                "error_details": None,
                "duration_ms": None,
                "related_scene_snapshot_id": None,
                "related_entry_ids": None,
                "file_path": None,
                "paths": None,
                "code": None,
                "created_at": now,
                "updated_at": now,
            }
            invocations.append(row)
        def _can_trans(a, b):
            trans = {
                "received": ["running", "cancelled", "failed"],
                "running": ["succeeded", "failed", "cancelled"],
                "succeeded": [],
                "failed": [],
                "cancelled": [],
            }
            return b in trans.get(a, [])
        if row["status"] == "received" and _can_trans("received", "running"):
            row["status"] = "running"
        row["updated_at"] = now
        if status != "running" and _can_trans(row["status"], status):
            row["status"] = status
        if response_body is not None:
            row["response_body"] = response_body
        if error_message is not None:
            row["error_message"] = error_message
        if error_details is not None:
            row["error_details"] = error_details
        if duration_ms is not None:
            row["duration_ms"] = duration_ms
        if file_path is not None:
            row["file_path"] = file_path
        if related_entry_ids is not None:
            row["related_entry_ids"] = related_entry_ids
        _save("tool_invocations.json", invocations)

    if not isinstance(path, str):
        return _err("VALIDATION_ERROR", "path must be a string")

    # Resolve active connected session
    sessions = _load("unity_editor_sessions.json")
    def _is_connected_active(s):
        if s.get("status") != "connected":
            return False
        hb = s.get("last_heartbeat_at")
        dt = _parse_iso(hb) if isinstance(hb, str) else None
        if dt is None:
            return False
        age = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - dt.astimezone(datetime.timezone.utc)
        return age.total_seconds() <= 30

    active = None
    for s in sorted(sessions, key=lambda r: (r.get("last_heartbeat_at") or "", r.get("updated_at") or ""), reverse=True):
        if _is_connected_active(s) and isinstance(s.get("assets_root_path"), str) and s.get("assets_root_path").endswith("/Assets"):
            active = s
            break
    if active is None:
        _record_invocation(
            "failed",
            {"_session_id": None, "path": path},
            error_message="No active connected Unity Editor session",
            error_details=_err("UNAUTHORIZED", "No active connected Unity Editor session")["error"],
            duration_ms=int((time.time() - t0) * 1000),
        )
        return _err("UNAUTHORIZED", "No active connected Unity Editor session")

    assets_root = active["assets_root_path"]
    sess_id = active["id"]

    raw = path.strip()
    def _norm_rel_assets(p):
        if p == "":
            return ""
        p = p.replace("\\", "/")
        if p == "Assets":
            return ""
        if p.startswith("Assets/"):
            p = p[len("Assets/"):]
        if p.startswith("/"):
            return None
        segs = []
        for part in p.split("/"):
            if part in ("", "."):
                continue
            if part == "..":
                return None
            segs.append(part)
        return "/".join(segs)

    def _resolve_to_abs(p):
        if p == "":
            return assets_root, ""
        p2 = p.replace("\\", "/")
        if os.path.isabs(p2):
            abs_candidate = os.path.normpath(p2)
            try:
                common = os.path.commonpath([os.path.abspath(abs_candidate), os.path.abspath(assets_root)])
            except Exception:
                return None, None
            if common != os.path.abspath(assets_root):
                return None, None
            rel = os.path.relpath(abs_candidate, assets_root).replace("\\", "/")
            rel = "" if rel == "." else rel
            rel_norm = _norm_rel_assets(rel)
            if rel_norm is None and rel != "":
                return None, None
            return (os.path.join(assets_root, rel_norm) if rel_norm != "" else assets_root), (rel_norm or "")
        rel_norm = _norm_rel_assets(p2)
        if rel_norm is None:
            return None, None
        return (os.path.join(assets_root, rel_norm) if rel_norm != "" else assets_root), rel_norm

    abs_p, rel_p = _resolve_to_abs(raw)
    if abs_p is None:
        _record_invocation(
            "failed",
            {"_session_id": sess_id, "path": path},
            error_message="Malformed path or outside Assets",
            error_details=_err("VALIDATION_ERROR", "Malformed path or outside Assets")["error"],
            duration_ms=int((time.time() - t0) * 1000),
        )
        return _err("VALIDATION_ERROR", "Malformed path or outside Assets")

    entries = _load("project_entries.json")
    def _find_entry():
        for e in entries:
            if e.get("session_id") == sess_id and e.get("path") == rel_p:
                return e
        return None

    e = _find_entry()
    exists_fs = os.path.exists(abs_p)
    if not exists_fs and not (e and e.get("status") == "present"):
        _record_invocation(
            "failed",
            {"_session_id": sess_id, "path": path},
            error_message="No file or directory exists at the given path",
            error_details=_err("NOT_FOUND", "No file or directory exists at the given path")["error"],
            duration_ms=int((time.time() - t0) * 1000),
            file_path=rel_p,
        )
        return _err("NOT_FOUND", "No file or directory exists at the given path")

    touched_ids = []
    # If not indexed or stale, stat and upsert/update entry.
    if exists_fs:
        st = os.stat(abs_p)
        is_dir = os.path.isdir(abs_p)
        name = "Assets" if rel_p == "" else rel_p.split("/")[-1]
        parent_path = None if rel_p == "" else ("/".join(rel_p.split("/")[:-1]) or "")
        if parent_path == "":
            parent_path = ""  # parent of direct children is Assets root (represented as "")
        if rel_p == "":
            parent_path = None

        entry_type = "directory" if is_dir else "file"
        ext = None
        if entry_type == "file":
            base = name
            if "." in base:
                ext = base.split(".")[-1].lower()
        size_bytes = None if is_dir else int(st.st_size)
        last_modified_at = datetime.datetime.utcfromtimestamp(st.st_mtime).replace(microsecond=0).isoformat() + "Z"

        if e is None:
            e = {
                "id": _new_id("entry"),
                "session_id": sess_id,
                "status": "present",
                "path": rel_p,
                "absolute_path": abs_p,
                "entry_type": entry_type,
                "parent_path": parent_path,
                "name": name,
                "extension": None if entry_type == "directory" else ext,
                "size_bytes": size_bytes,
                "content_hash_sha256": None,
                "last_modified_at": last_modified_at,
                "asset_type": None,
                "is_text": True if entry_type == "file" else False,
                "created_at": now,
                "updated_at": now,
            }
            # enforce constraints: extension null for directory, size>=0
            if e["size_bytes"] is not None and e["size_bytes"] < 0:
                e["size_bytes"] = 0
            if e["entry_type"] == "directory":
                e["extension"] = None
            entries.append(e)
            _save("project_entries.json", entries)
        else:
            changed = False
            if e.get("status") != "present":
                # legal transitions include deleted->present, ignored->present
                e["status"] = "present"
                changed = True
            if e.get("entry_type") != entry_type:
                e["entry_type"] = entry_type
                if entry_type == "directory":
                    e["extension"] = None
                    e["size_bytes"] = None
                    e["is_text"] = False
                changed = True
            if e.get("name") != name:
                e["name"] = name
                changed = True
            if e.get("parent_path") != parent_path:
                e["parent_path"] = parent_path
                changed = True
            if entry_type == "file":
                if e.get("extension") != ext:
                    e["extension"] = ext
                    changed = True
                if e.get("size_bytes") != size_bytes:
                    e["size_bytes"] = size_bytes
                    changed = True
                if e.get("last_modified_at") != last_modified_at:
                    e["last_modified_at"] = last_modified_at
                    changed = True
            else:
                if e.get("extension") is not None:
                    e["extension"] = None
                    changed = True
                if e.get("size_bytes") is not None:
                    e["size_bytes"] = None
                    changed = True
                if e.get("last_modified_at") != last_modified_at:
                    e["last_modified_at"] = last_modified_at
                    changed = True
            if changed:
                e["updated_at"] = now
                _save("project_entries.json", entries)

        touched_ids.append(e.get("id"))

    resp = {
        "path": rel_p,
        "absolute_path": abs_p if exists_fs else (e.get("absolute_path") if e else None),
        "exists": True,
        "entry_type": ("directory" if os.path.isdir(abs_p) else "file") if exists_fs else (e.get("entry_type") if e else None),
        "name": ("Assets" if rel_p == "" else rel_p.split("/")[-1]),
        "extension": (None if (exists_fs and os.path.isdir(abs_p)) else (e.get("extension") if e else None)),
        "size_bytes": (None if (exists_fs and os.path.isdir(abs_p)) else (int(os.stat(abs_p).st_size) if exists_fs else (e.get("size_bytes") if e else None))),
        "last_modified_at": (datetime.datetime.utcfromtimestamp(os.stat(abs_p).st_mtime).replace(microsecond=0).isoformat() + "Z") if exists_fs else (e.get("last_modified_at") if e else None),
        "status": e.get("status") if e else None,
        "asset_type": e.get("asset_type") if e else None,
        "is_text": e.get("is_text") if e else None,
        "content_hash_sha256": e.get("content_hash_sha256") if e else None,
        "entry_id": e.get("id") if e else None,
        "session_id": sess_id,
    }

    _record_invocation(
        "succeeded",
        {"_session_id": sess_id, "path": path},
        response_body=resp,
        duration_ms=int((time.time() - t0) * 1000),
        file_path=rel_p,
        related_entry_ids=touched_ids,
    )
    return resp

