            rel = os.path.relpath(abs_candidate, assets_root).replace("\\", "/")
            rel = "" if rel == "." else rel
            rel_norm = _norm_rel_assets(rel)
            if rel_norm is None and rel != "":
                return None
            return rel_norm or ""
        rel_norm = _norm_rel_assets(p2)
        return rel_norm

    base_rel = _resolve_to_rel(searchPath)
