    base_prefix = (base_rel + "/") if base_rel != "" else ""

    def _depth_ok(relp):
        if maxDepth == -1:
            return True
        if base_rel == "":
            # depth counts segments from Assets root: depth 1 means immediate children and root itself?
            # For directory search semantics: maxDepth=1 searches only in specified directory => include files directly under base, not deeper.
            # We'll interpret as: relative depth in segments beyond base directory must be 0.
            extra = relp.split("/") if relp != "" else []
            # base is root so extra segments length is depth
            return len(extra) <= maxDepth
        # base non-empty:
        if relp == base_rel:
            return True
        if not relp.startswith(base_prefix):
            return False
        tail = relp[len(base_prefix):]
        if tail == "":
            return True
        return (len(tail.split("/")) <= maxDepth)

