        relp = e.get("path")
        if not isinstance(relp, str):
            continue
        if base_rel != "":
            if not (relp == base_rel or relp.startswith(base_prefix)):
                continue
        if not _depth_ok(relp):
            continue
        results.append({
            "id": e.get("id"),
            "path": relp,
            "name": e.get("name"),
            "extension": e.get("extension"),
            "asset_type": e.get("asset_type"),
            "size_bytes": e.get("size_bytes"),
            "last_modified_at": e.get("last_modified_at"),
        })
