    if limit is None:
        limit = 50
    if not isinstance(limit, (int, float)) or (isinstance(limit, float) and not limit.is_integer()):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    limit = int(limit)
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")

    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")

    # Decode cursor (opaque). We encode offset as base64 of "o:<int>"
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if raw.startswith("o:"):
                offset = int(raw[2:])
                if offset < 0:
                    return _err("VALIDATION_ERROR", "cursor is invalid")
            else:
                return _err("VALIDATION_ERROR", "cursor is invalid")
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is invalid")

    # Filter
    rows = []
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if status is not None and s.get("status") != status:
            continue
        if mcp_client_id is not None and s.get("mcp_client_id") != mcp_client_id:
            continue
        if project_guid is not None and s.get("project_guid") != project_guid:
            continue
        if connection_name is not None and s.get("connection_name") != connection_name:
            continue
        rows.append(s)

    # Sort updated_at desc
    def _k(r):
        return (r.get("updated_at") or "", r.get("created_at") or "", r.get("id") or "")
    rows.sort(key=_k, reverse=True)

    total = len(rows)
    page = rows[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"o:{next_offset}".encode("utf-8")).decode("utf-8")

    resp = {
        "sessions": page,
        "total": total,
        "limit": limit,
        "cursor": cursor,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

    # Observable dynamics: record invocation
    invocations = _load("tool_invocations.json")
    inv_id = f"inv_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{os.urandom(8).hex()}"
    invocations.append({
        "id": inv_id,
        "session_id": page[0].get("id") if page else (rows[0].get("id") if rows else sessions[0].get("id")),
        "status": "succeeded",
        "tool_name": "verify_connection" if False else "get_editor_state" if False else "list_unity_editor_sessions",
        "request_params": {"status": status, "mcp_client_id": mcp_client_id, "project_guid": project_guid, "connection_name": connection_name, "limit": limit, "cursor": cursor},
        "response_body": {"returned": len(page), "total": total, "has_more": has_more},
        "error_message": None,
        "error_details": None,
        "duration_ms": int((time.time() - t0) * 1000),
        "related_scene_snapshot_id": None,
        "related_entry_ids": [],
        "file_path": None,
        "paths": None,
        "code": None,
        "created_at": now,
        "updated_at": now,
    })
    _save("tool_invocations.json", invocations)

    return resp

