            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _dt_to_iso(dt):
        if isinstance(dt, str):
            return dt
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log_invocation(session_id, tool_name, request_params, status, response_body=None, error_message=None, error_details=None):
        inv = _load("tool_invocations.json")
        now = _now()
        row = {
            "id": _new_id("inv"),
            "session_id": session_id,
            "status": status,
            "tool_name": tool_name,
            "request_params": request_params,
            "response_body": response_body,
            "error_message": error_message,
            "error_details": error_details,
            "duration_ms": None,
            "related_scene_snapshot_id": None,
            "related_entry_ids": None,
            "file_path": None,
            "paths": None,
            "code": None,
            "created_at": _dt_to_iso(now),
            "updated_at": _dt_to_iso(now),
        }
        inv.append(row)
        _save("tool_invocations.json", inv)
        return row["id"]

    start = time.time()
    tool_name = "get_unity_editor_session"
    request_params = {"id": id}

    # Validation
    if not isinstance(id, str) or not id.strip():
        # Can't associate with a session reliably; use a best-effort connected session if any for logging
        sessions = _load("unity_editor_sessions.json")
        sid = sessions[0]["id"] if sessions else "unknown"
        _log_invocation(sid, tool_name, request_params, "failed", error_message="Validation error", error_details={"field": "id"})
        return _err("VALIDATION_ERROR", "Parameter 'id' must be a non-empty string.", field="id")

    sessions = _load("unity_editor_sessions.json")
    sess = next((s for s in sessions if s.get("id") == id), None)

    if not sess:
        sid = sessions[0]["id"] if sessions else "unknown"
        _log_invocation(sid, tool_name, request_params, "failed", error_message="Not found", error_details={"id": id})
        return _err("NOT_FOUND", "Unity Editor session not found.", id=id)

    # Ambient auth: if caller reached here, assume authorized for this local datastore.
    # Record invocation (reads included)
    _log_invocation(sess.get("id", "unknown"), tool_name, request_params, "succeeded", response_body={"session": sess})
    duration_ms = int((time.time() - start) * 1000)

    # Patch duration_ms into the last invocation we wrote (best-effort, no blanket exceptions)
    inv = _load("tool_invocations.json")
    for r in reversed(inv):
        if r.get("tool_name") == tool_name and r.get("session_id") == sess.get("id"):
            if r.get("duration_ms") is None:
                r["duration_ms"] = max(0, duration_ms)
                r["updated_at"] = _dt_to_iso(_now())
                _save("tool_invocations.json", inv)
            break

    return {"session": sess}

def update_unity_editor_session(id, status=None, connection_name=None, last_seen_scene_path=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0289000" if __import__("os").path.isdir("./environment_mix/0289000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _dt_to_iso(dt):
        if isinstance(dt, str):
            return dt
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log_invocation(session_id, tool_name, request_params, status_, response_body=None, error_message=None, error_details=None):
        inv = _load("tool_invocations.json")
        now = _now()
        row = {
            "id": _new_id("inv"),
            "session_id": session_id,
            "status": status_,
            "tool_name": tool_name,
            "request_params": request_params,
            "response_body": response_body,
            "error_message": error_message,
            "error_details": error_details,
            "duration_ms": None,
            "related_scene_snapshot_id": None,
            "related_entry_ids": None,
            "file_path": None,
            "paths": None,
            "code": None,
            "created_at": _dt_to_iso(now),
            "updated_at": _dt_to_iso(now),
        }
        inv.append(row)
        _save("tool_invocations.json", inv)
        return row["id"]

    start = time.time()
    tool_name = "update_unity_editor_session"
    request_params = {"id": id}
    if status is not None:
        request_params["status"] = status
    if connection_name is not None:
        request_params["connection_name"] = connection_name
    if last_seen_scene_path is not None:
        request_params["last_seen_scene_path"] = last_seen_scene_path

    # Validation
    if not isinstance(id, str) or not id.strip():
        sessions = _load("unity_editor_sessions.json")
        sid = sessions[0]["id"] if sessions else "unknown"
        _log_invocation(sid, tool_name, request_params, "failed", error_message="Validation error", error_details={"field": "id"})
        return _err("VALIDATION_ERROR", "Parameter 'id' must be a non-empty string.", field="id")

    allowed_status = {"connected", "disconnected", "stale", "terminated"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        sessions = _load("unity_editor_sessions.json")
        sid = next((s["id"] for s in sessions if s.get("id") == id), sessions[0]["id"] if sessions else "unknown")
        _log_invocation(sid, tool_name, request_params, "failed", error_message="Validation error", error_details={"field": "status"})
        return _err("VALIDATION_ERROR", "Invalid 'status' value.", field="status", allowed=sorted(allowed_status))

    if connection_name is not None and not isinstance(connection_name, str):
        sessions = _load("unity_editor_sessions.json")
        sid = next((s["id"] for s in sessions if s.get("id") == id), sessions[0]["id"] if sessions else "unknown")
        _log_invocation(sid, tool_name, request_params, "failed", error_message="Validation error", error_details={"field": "connection_name"})
        return _err("VALIDATION_ERROR", "Parameter 'connection_name' must be a string.", field="connection_name")

    if last_seen_scene_path is not None and not isinstance(last_seen_scene_path, str):
        sessions = _load("unity_editor_sessions.json")
        sid = next((s["id"] for s in sessions if s.get("id") == id), sessions[0]["id"] if sessions else "unknown")
        _log_invocation(sid, tool_name, request_params, "failed", error_message="Validation error", error_details={"field": "last_seen_scene_path"})
        return _err("VALIDATION_ERROR", "Parameter 'last_seen_scene_path' must be a string.", field="last_seen_scene_path")

    sessions = _load("unity_editor_sessions.json")
    idx = next((i for i, s in enumerate(sessions) if s.get("id") == id), None)
    if idx is None:
        sid = sessions[0]["id"] if sessions else "unknown"
        _log_invocation(sid, tool_name, request_params, "failed", error_message="Not found", error_details={"id": id})
        return _err("NOT_FOUND", "Unity Editor session not found.", id=id)

    sess = sessions[idx]

    # Lifecycle transitions
    transitions = {
        "connected": {"disconnected", "stale", "terminated"},
        "disconnected": {"connected", "terminated"},
        "stale": {"connected", "terminated"},
        "terminated": set(),
    }
    if status is not None:
        cur = sess.get("status")
        if cur not in transitions:
            _log_invocation(sess.get("id", "unknown"), tool_name, request_params, "failed",
                            error_message="Validation error",
                            error_details={"field": "status", "reason": "Unknown current lifecycle state", "current": cur})
            return _err("VALIDATION_ERROR", "Session has invalid current status in store.", current=cur)
        if status != cur and status not in transitions[cur]:
            _log_invocation(sess.get("id", "unknown"), tool_name, request_params, "failed",
                            error_message="Invalid transition",
                            error_details={"current": cur, "requested": status, "allowed": sorted(transitions[cur])})
            return _err("INVALID_TRANSITION", "Requested status transition is not allowed.", current=cur, requested=status, allowed=sorted(transitions[cur]))

    # Uniqueness: unique(project_guid, connection_name) where both not null
    new_connection_name = connection_name if connection_name is not None else sess.get("connection_name")
    project_guid = sess.get("project_guid")
    if project_guid is not None and new_connection_name is not None:
        for s in sessions:
            if s.get("id") == id:
                continue
            if s.get("project_guid") == project_guid and s.get("connection_name") == new_connection_name:
                _log_invocation(sess.get("id", "unknown"), tool_name, request_params, "failed",
                                error_message="Conflict",
                                error_details={"constraint": "unique(project_guid, connection_name)", "project_guid": project_guid, "connection_name": new_connection_name})
                return _err("CONFLICT", "Another session already uses this (project_guid, connection_name).",
                            project_guid=project_guid, connection_name=new_connection_name)

    # Apply updates
    now = _now()
    changed = False

    if status is not None and status != sess.get("status"):
        sess["status"] = status
        changed = True

    if connection_name is not None and connection_name != sess.get("connection_name"):
        sess["connection_name"] = connection_name
        changed = True

    if last_seen_scene_path is not None and last_seen_scene_path != sess.get("last_seen_scene_path"):
        sess["last_seen_scene_path"] = last_seen_scene_path
        changed = True

    if not changed:
        # Still counts as a real call; record succeeded read-like mutation with no changes is acceptable if record exists,
        # but ensure we don't claim mutation effects beyond update_at. We'll still refresh updated_at to reflect write intent?
        # Real services often are idempotent; here we'll update updated_at to now to reflect the update call.
        sess["updated_at"] = _dt_to_iso(now)
        sessions[idx] = sess
        _save("unity_editor_sessions.json", sessions)
    else:
        sess["updated_at"] = _dt_to_iso(now)
        sessions[idx] = sess
        _save("unity_editor_sessions.json", sessions)

    _log_invocation(sess.get("id", "unknown"), tool_name, request_params, "succeeded", response_body={"session": sess})
    duration_ms = int((time.time() - start) * 1000)

    inv = _load("tool_invocations.json")
    for r in reversed(inv):
        if r.get("tool_name") == tool_name and r.get("session_id") == sess.get("id"):
            if r.get("duration_ms") is None:
                r["duration_ms"] = max(0, duration_ms)
                r["updated_at"] = _dt_to_iso(_now())
                _save("tool_invocations.json", inv)
            break

    return {"session": sess}

