    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _encode_cursor({"v": 1, "session_id": session_id_use, "status": status, "scene_path": scene_path, "offset": next_offset}) if has_more else None

    response = {
        "snapshots": page,
        "meta": {"total": total, "limit": limit_val, "has_more": has_more, "next_cursor": next_cursor},
    }

    _log_invocation(session_id_use, tool_name, request_params, "succeeded", response_body=response)
    duration_ms = int((time.time() - start) * 1000)

    inv = _load("tool_invocations.json")
    for r in reversed(inv):
        if r.get("tool_name") == tool_name and r.get("session_id") == session_id_use:
            if r.get("duration_ms") is None:
                r["duration_ms"] = max(0, duration_ms)
                r["updated_at"] = _dt_to_iso(_now())
                _save("tool_invocations.json", inv)
            break

    return response

def update_scene_snapshot(id, status, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0289000" if __import__("os").path.isdir("./environment_mix/0289000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _dt_dump(d):
        if d is None:
            return None
        if isinstance(d, str):
            return d
        if not isinstance(d, datetime.datetime):
            return None
        return d.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _pick_active_session(sessions, staleness_window_seconds=30):
        now = _now()
        best = None
        best_hb = None
        for s in sessions:
            if not isinstance(s, dict):
                continue
            if s.get("status") != "connected":
                continue
            hb_raw = s.get("last_heartbeat_at")
            hb = None
            if isinstance(hb_raw, str):
                x = hb_raw.strip()
                if x.endswith("Z"):
                    x = x[:-1] + "+00:00"
                try:
                    hb = datetime.datetime.fromisoformat(x)
                    if hb.tzinfo is None:
                        hb = hb.replace(tzinfo=datetime.timezone.utc)
                except Exception:
                    hb = None
            elif isinstance(hb_raw, datetime.datetime):
                hb = hb_raw if hb_raw.tzinfo else hb_raw.replace(tzinfo=datetime.timezone.utc)
            if hb is None:
                continue
            age = (now - hb).total_seconds()
            if age < 0:
                age = 0
            if age <= staleness_window_seconds:
                if best is None or hb > best_hb:
                    best = s
                    best_hb = hb
        return best, staleness_window_seconds

    def _record_inv(session_id, status_, request_params, response_body=None, error_message=None, error_details=None, related_scene_snapshot_id=None):
        invocations = _load("tool_invocations.json")
        now_dt = _now()
        row = {
            "id": _new_id("unity_inv"),
            "session_id": session_id,
            "status": status_,
            "tool_name": "update_scene_snapshot",
            "request_params": request_params if isinstance(request_params, dict) else {},
            "response_body": response_body,
            "error_message": error_message,
            "error_details": error_details,
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "related_scene_snapshot_id": related_scene_snapshot_id,
            "related_entry_ids": None,
            "file_path": None,
            "paths": None,
            "code": None,
            "created_at": _dt_dump(now_dt),
            "updated_at": _dt_dump(now_dt),
        }
        invocations.append(row)
        _save("tool_invocations.json", invocations)
        return row

    # Validate inputs
    if not isinstance(id, str) or id.strip() == "":
        sessions = _load("unity_editor_sessions.json")
        active, _ = _pick_active_session(sessions)
        sid = active.get("id") if active else (sessions[0].get("id") if sessions and isinstance(sessions[0], dict) else "unknown_session")
        _record_inv(sid, "failed", {"id": id, "status": status},
                    error_message="Validation error",
                    error_details=_err("VALIDATION_ERROR", "id must be a non-empty string.", field="id")["error"])
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", field="id")

    if not isinstance(status, str) or status not in ["captured", "superseded", "invalid"]:
        sessions = _load("unity_editor_sessions.json")
        active, _ = _pick_active_session(sessions)
        sid = active.get("id") if active else (sessions[0].get("id") if sessions and isinstance(sessions[0], dict) else "unknown_session")
        _record_inv(sid, "failed", {"id": id, "status": status},
                    error_message="Validation error",
                    error_details=_err("VALIDATION_ERROR", "status must be one of: captured, superseded, invalid.", field="status")["error"])
        return _err("VALIDATION_ERROR", "status must be one of: captured, superseded, invalid.", field="status")

    # Authorization: any active connected session in store can mutate snapshots (ambient auth)
    sessions = _load("unity_editor_sessions.json")
    active, _ = _pick_active_session(sessions)
    if not active:
        sid = sessions[0].get("id") if sessions and isinstance(sessions[0], dict) else "unknown_session"
        _record_inv(sid, "failed", {"id": id, "status": status},
                    error_message="No active Unity Editor connection",
                    error_details=_err("UNAUTHORIZED", "No active Unity Editor connection (no connected session within staleness window).")["error"],
                    related_scene_snapshot_id=id)
        return _err("UNAUTHORIZED", "No active Unity Editor connection (no connected session within staleness window).")

    session_id = active.get("id")

    snapshots = _load("scene_snapshots.json")
    snap = None
    for s in snapshots:
        if isinstance(s, dict) and s.get("id") == id:
            snap = s
            break

    if not snap:
        # Also handle audit defect where caller mistakenly passed a session id: return NOT_FOUND with rule info.
        _record_inv(session_id, "failed", {"id": id, "status": status},
                    error_message="Snapshot not found",
                    error_details=_err("NOT_FOUND", "Scene snapshot not found. Rule: update_scene_snapshot operates on scene_snapshots.id, not unity_editor_sessions.id.", id=id)["error"],
                    related_scene_snapshot_id=id)
        return _err("NOT_FOUND", "Scene snapshot not found. Rule: update_scene_snapshot operates on scene_snapshots.id, not unity_editor_sessions.id.", id=id)

    # Enforce lifecycle transitions
    current = snap.get("status")
    allowed = {
        "captured": ["superseded", "invalid"],
        "superseded": [],
        "invalid": []
    }
    if current not in allowed:
        _record_inv(session_id, "failed", {"id": id, "status": status},
                    error_message="Validation error",
                    error_details=_err("VALIDATION_ERROR", "Snapshot has invalid current status in datastore.", id=id, current_status=current)["error"],
                    related_scene_snapshot_id=id)
        return _err("VALIDATION_ERROR", "Snapshot has invalid current status in datastore.", id=id, current_status=current)

    if status == current:
        # idempotent
        _record_inv(session_id, "succeeded", {"id": id, "status": status},
                    response_body={"snapshot": snap},
                    related_scene_snapshot_id=id)
        return {"snapshot": snap}

    if status not in allowed[current]:
        _record_inv(session_id, "failed", {"id": id, "status": status},
                    error_message="Invalid transition",
                    error_details=_err("INVALID_TRANSITION", "Requested status transition is not allowed by snapshot lifecycle rules.",
                                      id=id, from_status=current, to_status=status, allowed=allowed[current])["error"],
                    related_scene_snapshot_id=id)
        return _err("INVALID_TRANSITION", "Requested status transition is not allowed by snapshot lifecycle rules.",
                    id=id, from_status=current, to_status=status, allowed=allowed[current])

    now_dt = _now()
    snap["status"] = status
    snap["updated_at"] = _dt_dump(now_dt)
    if not snap.get("created_at"):
        snap["created_at"] = _dt_dump(now_dt)

    _save("scene_snapshots.json", snapshots)

    _record_inv(session_id, "succeeded", {"id": id, "status": status},
                response_body={"snapshot": snap},
                related_scene_snapshot_id=id)
    return {"snapshot": snap}
